(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c10"]=[{"id":"00000098","register_sub_id":"101","register_pk":"101088","name":"明倫小学校本館","kana":"めいりんしょうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県萩市大字江向602","lat":34.40921795,"lng":131.39976123,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1104㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"35 － 0001","desc":"隣接する史跡有備館に合わせた意匠で，外壁は１階部分は押しぶち下見板張り，２階部分は白漆喰塗りである。屋根のフランス瓦や連続する窓の意匠が特徴的で，モダニズムへの萌芽も見られる。既にほとんど失われてしまった木造学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000098"},{"id":"00001293","register_sub_id":"101","register_pk":"102283","name":"山口県立山口高等学校記念館（旧制山口高等学校講堂）","kana":"やまぐちけんりつやまぐちこうとうがっこうきねんかん（きゅうせいやまぐちこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県山口市糸米1-9-1","lat":34.17482707,"lng":131.46670514,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，銅板葺，建築面積371㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"35 － 0024","desc":"高等学校令に基づきつくられた学校建築。マンサード屋根の主体部の正面左右に三角屋根の塔屋が取り付いた形で，幾何学的な装飾を多用した点によく時代の特徴があらわれている。文部省建築課山口出張所が建設したもので，同省技師の谷口鼎が担当した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001293"},{"id":"00010689","register_sub_id":"101","register_pk":"201263","name":"徳島県立城北高等学校人形会館","kana":"とくしまけんりつじょうほくこうとうがっこうにんぎょうかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"徳島県","address":"徳島県徳島市北田宮4-13-6","lat":34.08888,"lng":134.531294,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積282㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0125","desc":"人形浄瑠璃の盛んな当地で、学校に併設された本格的な芝居小屋。舞台は二段構成とし、右手前に太夫座を張出す。舞台上部に葡萄棚を設けて舞台裏に控室などを配し、客席は升席とする。海鼠壁と赤塗の高欄ともに特徴的な外観になり、伝統芸能の伝承拠点となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010689"},{"id":"00001142","register_sub_id":"101","register_pk":"102132","name":"粟島海洋記念館研修棟（旧粟島海員学校教室）","kana":"あわしまかいようきねんかんけんしゅうとう（きゅうあわしまかいいんがっこうきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26823731,"lng":133.63134796,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積471㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0022","desc":"資料室に隣接して敷地の西側に建つ南北棟の建物で，片廊下型の教室棟を研修施設としたもの。外観は，概ね本館に意匠をあわせた形だが，正面にみせた妻飾や出入口上部に付けた庇の意匠を本館正面とかえるなどの工夫もみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001142"},{"id":"00001141","register_sub_id":"101","register_pk":"102131","name":"粟島海洋記念館資料館（旧粟島海員学校教室）","kana":"あわしまかいようきねんかんしりょうかん（きゅうあわしまかいいんがっこうきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26837193,"lng":133.63156509,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積280㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0021","desc":"本館の西に隣接して建つ木造平屋建，片廊下型平面の教室棟を海洋関係の資料展示室としたもの。海から見える正面側は本館と意匠をあわせ，校庭に面した背面側の意匠は簡略なものとしている。本館とともに海員学校正面の堂々とした構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001141"},{"id":"00001143","register_sub_id":"101","register_pk":"102133","name":"粟島海洋記念館武道場（旧粟島海員学校柔道場）","kana":"あわしまかいようきねんかんぶどうじょう（きゅうあわしまかいいんがっこうじゅうどうじょう）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.2686846,"lng":133.63140007,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積151㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0023","desc":"本館の後方に中庭を挟んで建つ木造平屋建の建物。本館等に比較すると外観の意匠はきわめて簡素だが，小屋組にトラスを用い内部に柱を立てないなど，柔道場にふさわしいつくりになる。往時の海員養成の様子を物語る施設のひとつとして貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001143"},{"id":"00001140","register_sub_id":"101","register_pk":"102130","name":"粟島海洋記念館本館（旧粟島海員学校本館）","kana":"あわしまかいようきねんかんほんかん（きゅうあわしまかいいんがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26854129,"lng":133.63178005,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造２階建，瓦葺，建築面積208㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0020","desc":"粟島海員学校は明治３０年に我が国最初の海員養成校として開校した。現在残る校舎等は大正９年の建築。本館は木造２階建で，２階を講堂にあてる。粟島のシンボル的な存在で，外壁の下見板や正面中央にみせたハーフティンバーの妻飾等に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001140"},{"id":"00001144","register_sub_id":"101","register_pk":"102134","name":"粟島海洋記念館門柱（旧粟島海員学校門柱）","kana":"あわしまかいようきねんかんもんちゅう（きゅうあわしまかいいんがっこうもんちゅう）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26840884,"lng":133.63193855,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造，高さ109cm","structure_material":"石造","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0024","desc":"地元産の花崗岩を用いてつくった門柱で，本館の正面に２本並んで建つ。４隅に傾斜を付けた大面を取り，上部中央を球状に仕上げるなど幾何学的なモチーフを用いた意匠は，よく時代の特徴をあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001144"},{"id":"00015514","register_sub_id":"101","register_pk":"533529","name":"香川県立善通寺第一高等学校（旧私立善通寺高等女学校）旧正門","kana":"かがわけんりつぜんつうじだいいちこうとうがっこう（きゅうしりつぜんつうじこうとうじょがっこう）きゅうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県善通寺市文京町一丁目1391","lat":34.22699722,"lng":133.78918333,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造、間口4.0m、左右脇門付","structure_material":"煉瓦造","registered":"2025.08.06(令和7.08.06)","register_no":"37 - 0493","desc":"ＪＲ善通寺駅南方に位置する旧女学校の正門。大正11年の陸軍特別大演習統監部設置を記念して建てた門で、親柱の東西脇に脇柱を配し、柱はいずれも花崗岩基礎に煉瓦を積上げ、頂部は花崗岩製の帯飾と笠石を載せる。煉瓦造の重厚な外観で地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015514"},{"id":"00000100","register_sub_id":"101","register_pk":"101090","name":"丸亀高校記念館（旧香川県立高松尋常中学校丸亀分校本館）","kana":"まるがめこうこうきねんかん（きゅうかがわけんりつたかまつじんじょうちゅうがっこうまるがめぶんこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市6-1","lat":34.28270339,"lng":133.7974882,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積694㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0001","desc":"香川県立の尋常中学校分校の本館として建設されたもので，２階を講堂，１階を職員室としていた。下見板，正面の玄関ポーチ，ペディメントのついた上下窓等を用いた洋風の意匠をもつ建物で，明治期の学校建築の技術の水準の高さをよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000100"},{"id":"00000746","register_sub_id":"101","register_pk":"101736","name":"愛媛大学附属中学校講堂（旧旧制松山高等学校講堂）","kana":"えひめだいがくふぞくちゅうがっこうこうどう（きゅうきゅうせいまつやまこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市持田町1-5-22","lat":33.84227013,"lng":132.78212241,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，建築面積501㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"38 － 0002","desc":"文部省営繕による直轄学校の講堂建築。文部技師の鳥海他郎の設計と推定される。２階にギャラリーを設けるなど設備面では定型的であるが，外見はドイツ下見により穏健なルネサンス風に仕上げ，トスカナ式オーダーの大きな車寄に特徴をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000746"},{"id":"00013765","register_sub_id":"101","register_pk":"505327","name":"西条栄光幼稚園園舎","kana":"さいじょうえいこうようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県西条市明屋敷字旧陣屋内236-17他","lat":33.92116111,"lng":133.17899444,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積351㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 153","desc":"礼拝堂の西に渡廊下で接続。平屋建切妻造桟瓦葺。長大な平面に保育室等を配する。南の園庭に面した屋外廊下は円柱と矩形の開口が並び、天井と面一とした軒の高窓からは自然光が入る、木造モダニズムの佳品。隣接三棟で意匠を微妙に変えた設計に妙味がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013765"},{"id":"00014542","register_sub_id":"101","register_pk":"513956","name":"高知追手前高等学校本館","kana":"こうちおうてまえこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高知市追手筋二丁目2-10","lat":33.56160833,"lng":133.53649444,"geo_status":"db","era":"昭和6年／同中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1，758㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"39 - 0308","desc":"高知城に通じる追手筋に面して建つ。鉄筋コンクリート造三階建で、左右に翼部を設け、屋上に奉安所を構える。武田五一指導のもと県営繕技師高崎正隆が設計を担当。左右対称の外観の中央に宝形屋根の高塔が聳える記念碑的な外観。県下を代表する近代学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014542"},{"id":"00015394","register_sub_id":"101","register_pk":"532518","name":"旧九州芸術工科大学音響特殊施設棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくおんきょうとくしゅしせつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56023611,"lng":130.43085,"geo_status":"db","era":"昭和45年／令和3年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積372㎡、渡廊下付","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0234","desc":"広場南東に位置し、無響室など配する音響工学専門施設。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造3階建、躯体打放仕上。二階レベルで中庭状広場と接続。画像特殊施設棟の立面を反転、渡廊下を挟んで左右対称の外観とし、二棟で広場東面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015394"},{"id":"00015393","register_sub_id":"101","register_pk":"532517","name":"旧九州芸術工科大学画像特殊施設棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくがぞうとくしゅしせつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56045556,"lng":130.43086389,"geo_status":"db","era":"昭和45年／令和元年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積275㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0233","desc":"広場の北東に位置し写真スタジオなど配する画像工学専門施設。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造3階建、躯体打放仕上。二階レベルで中庭状の広場に接続。中央玄関上部の壁面を浅く窪ませてバルコニーとし、左右対称の均整取れた外観の校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015393"},{"id":"00015391","register_sub_id":"101","register_pk":"532515","name":"旧九州芸術工科大学環境画像棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくかんきょうがぞうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56063889,"lng":130.43052778,"geo_status":"db","era":"昭和45年／平成26年・令和元年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造6階建、建築面積808㎡、広場付","structure_material":"鉄筋コンクリート造6階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0231","desc":"西鉄大橋駅東方にある大学校舎。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造6階建、躯体打放仕上。下層を吹抜ラウンジ、上層をバルコニーとした階段状の立面が２階レベルの中庭状広場と巧みに調和。香山によるキャンパス計画の中心的な校舎の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015391"},{"id":"00015392","register_sub_id":"101","register_pk":"532516","name":"旧九州芸術工科大学工業音響棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくこうぎょうおんきょうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56009167,"lng":130.43048333,"geo_status":"db","era":"昭和45年／令和3年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造6階建、建築面積813㎡","structure_material":"鉄筋コンクリート造6階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0232","desc":"環境画像棟と中庭状の広場を挟み正対して建つ校舎。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造6階建、躯体打放仕上。上層をセットバックした変化のある外観で二階レベルで広場に接続する。環境画像棟と同意匠で対峙し、壮麗な広場景観をつくる校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015392"},{"id":"00015395","register_sub_id":"101","register_pk":"532519","name":"旧九州芸術工科大学工作工房","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくこうさくこうぼう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56035278,"lng":130.43014167,"geo_status":"db","era":"昭和45年／平成26年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造3階一部2階建、建築面積486㎡","structure_material":"鉄筋コンクリート造3階一部2階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0235","desc":"広場の南西に位置し、デッサンや木工用の作業棟。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造3階建、躯体打放仕上。2階レベルで接続する広場から正面渡廊下の下を潜り抜けて小広場に至る。中央を見通す左右対称の均整取れた外観で広場の一角を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015395"},{"id":"00014543","register_sub_id":"101","register_pk":"513957","name":"旧九州帝国大学工学部本館","kana":"きゅうきゅうしゅうていこくだいがくこうがくぶほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62278611,"lng":130.42535,"geo_status":"db","era":"昭和5年／昭和63年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造地上3階地下1階建、建築面積3，152㎡、塔屋付","structure_material":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造地上3階地下1階建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0207","desc":"鉄筋コンクリート造３階地下１階建の校舎。中央塔屋の両脇には半円筒の張出を付し、外壁はスクラッチタイル貼で腰を石張、上層はアール付の役物タイルで陰影をつける。内部には意匠に凝った会議室や大講義室が残る。城塞のような重厚な外観がシンボリック。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014543"},{"id":"00015103","register_sub_id":"101","register_pk":"529381","name":"旧九州帝国大学正門及び塀","kana":"きゅうきゅうしゅうていこくだいがくせいもんおよびへい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62141667,"lng":130.42561389,"geo_status":"db","era":"大正3年／大正13年移築、令和5年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門柱 煉瓦造、間口4.5m、脇門付 塀 コンクリートブロック造及び煉瓦造、総延長41m","structure_material":"門柱 煉瓦造","registered":"2024.08.15(令和6.08.15)","register_no":"40 - 0225","desc":"通りに東面して建つ旧正門と両脇に続く塀。正門門柱は煉瓦造の角柱で頂部を古典主義的意匠の花崗岩で飾り、左右は控柱を立て通用口とする。塀はコンクリートブロック造壁体に石製笠木を置き、煉瓦造の柵柱を立てる。大学を象徴する重厚な外観の正門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015103"},{"id":"00014545","register_sub_id":"101","register_pk":"513959","name":"旧九州帝国大学本部建築課棟","kana":"きゅうきゅうしゅうていこくだいがくほんぶけんちくかとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62196389,"lng":130.42581111,"geo_status":"db","era":"大正14年／昭和40年・同48年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造地上2階地下1階建、建築面積230㎡、塔屋付","structure_material":"煉瓦造地上2階地下1階建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0209","desc":"工学部本館の南東に位置する煉瓦造２階地下1階建の建築課棟。西面中央を玄関として塔屋を載せ、内部は中廊下式平面とする。外壁は化粧煉瓦で、腰と軒をモルタル洗出仕上とし、塔屋の窓上部を石造アーチで飾る。均整の取れた外観は事務室棟と共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014545"},{"id":"00014544","register_sub_id":"101","register_pk":"513958","name":"旧九州帝国大学本部事務室棟","kana":"きゅうきゅうしゅうていこくだいがくほんぶじむしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62243056,"lng":130.42605833,"geo_status":"db","era":"大正14年／昭和39年・同43年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造2階建、建築面積1，276㎡、塔屋付","structure_material":"煉瓦造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0208","desc":"工学部本館と相対する煉瓦造２階建の事務室棟。西面中央の玄関に塔屋を載せ、内部は中廊下式平面で、中央階段上部を吹抜とする。外壁は化粧煉瓦で、腰と上層はモルタル洗出で石張風。窓廻りやアーチの要所を花崗岩で飾る。整った外観は校舎の時代差を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014544"},{"id":"00014546","register_sub_id":"101","register_pk":"513960","name":"旧九州帝国大学門衛所","kana":"きゅうきゅうしゅうていこくだいがくもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62155,"lng":130.42561944,"geo_status":"db","era":"大正3年／同13年移築、昭和33年・平成24年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造平屋建、スレート葺、建築面積29㎡","structure_material":"煉瓦造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0210","desc":"工学部本館の南に位置する煉瓦造平屋建、寄棟造スレート葺の門衛所。Ｌ字型平面で南を玄関とし、内部は事務室と休憩室の２室とする。玄関上部はブロークンペディメントで飾り、窓廻りは要所の花崗岩で意匠を凝らす。装飾豊かな外観で箱崎地区最古の門衛所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014546"},{"id":"00013666","register_sub_id":"101","register_pk":"504896","name":"久留米大学本館","kana":"くるめだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県久留米市旭町67","lat":33.32870833,"lng":130.51114167,"geo_status":"db","era":"昭和4年／昭和58年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、陸屋根、建築面積1297㎡、西面・南面スロープ及び中庭階段付","structure_material":"鉄筋コンクリート造3階建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0182","desc":"久留米城の東に位置。設計は松田昌平で施工は松田組。コの字形平面で、正面二階の中央に車寄玄関を設けロンバルティア帯で飾る。車寄上部を三連アーチ窓とし、両翼は三層を通した二連のアーチ枠を並べて窓を穿つ。ロマネスクを基調とした格調高い大学本館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013666"},{"id":"00009080","register_sub_id":"101","register_pk":"162440","name":"筑紫女学園香風亭","kana":"ちくしじょがくえんこうふうてい","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区警固2-24-3","lat":33.58267391,"lng":130.3889483,"geo_status":"db","era":"昭和30年／平成15年改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"40 － 0071","desc":"洗心庵の南に位置する。南北棟の切妻造桟瓦葺で、軒先を銅板葺とし、北面に角屋を付設する。十畳の主座敷と十五畳の次の間を中心に縁を廻らして下屋とし、三畳台目の茶室や納戸、玄関を付ける。装飾を廃した開放的な書院座敷で、品格ある雰囲気を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009080"},{"id":"00009078","register_sub_id":"101","register_pk":"162438","name":"筑紫女学園洗心庵","kana":"ちくしじょがくえんせんしんあん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固2-24-3","lat":33.58280176,"lng":130.38904012,"geo_status":"db","era":"昭和15年／平成15年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"40 － 0069","desc":"校地の東北隅に位置する。北に四畳半の茶室、南に六畳の水屋を配し、茶室には台目のトコを構え、水屋にも丸炉を切る。屋根は東西棟からＴ字型に南北棟が延び、妻などに土庇を付設する。丸太柱を多用し、外壁は漆喰仕上げとする。軽快で変化に富む外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009078"},{"id":"00009079","register_sub_id":"101","register_pk":"162439","name":"筑紫女学園待合","kana":"ちくしじょがくえんまちあい","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固2-24-3","lat":33.58275178,"lng":130.38914123,"geo_status":"db","era":"昭和15年／平成15年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"40 － 0070","desc":"洗心庵東南に位置する。桁行1.8メートル梁間南0.9メートル北0.6メートル、招屋根杉皮葺。丸太柱で側・背面を漆喰仕上げ真壁とし、南妻に下地窓を開ける。南北で妻壁の出を変え、座板は途中で折れ、杉板と竹を交互に張る。繊細なデザインの庭園建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009079"},{"id":"00001309","register_sub_id":"101","register_pk":"102299","name":"如蘭塾塾舎及び寄宿舎","kana":"じょらんじゅくじゅくしゃおよびきしゅくしゃ","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県武雄市武雄町大字武雄4322","lat":33.18456286,"lng":130.02336345,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建一部２階建，瓦葺，建築面積489㎡","structure_material":"木造平屋建一部２階建","registered":"1999.08.23(平成11.08.23)","register_no":"41 － 0012","desc":"中国子女の留学施設として実業家野中忠太が開設した如蘭塾の主要施設で、玄関及び教室等からなる東西棟の塾舎に、南北棟の寄宿舎棟がＬ型に取り付く。設計は当時満州で活躍していた遠藤新といわれ、凝灰岩を用いた玄関の親柱はライト風の独特の構えになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001309"},{"id":"00014436","register_sub_id":"101","register_pk":"511425","name":"脊振小学校石門","kana":"せふりしょうがっこういしもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県神埼市脊振町広滝字井ノ上574-1","lat":33.37722778,"lng":130.32740278,"geo_status":"db","era":"大正3年／昭和30年移築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"石造、間口7.1m","structure_material":"石造","registered":"2022.10.31(令和4.10.31)","register_no":"41 - 0130","desc":"市北部の山間に所在する小学校の門。高さ四・三メートル、一・〇九メートル角の花崗岩江戸切り仕上の石柱を、間口７・１メートルに立てる。石材は裏山の石切り場で切り出し、大正天皇即位記念で村民有志が建設した。学校のシンボルで、稀に見る大きさの石門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014436"},{"id":"00008074","register_sub_id":"101","register_pk":"128905","name":"旧波佐見町立中央小学校講堂兼公会堂","kana":"きゅうはさみちょうりつちゅうおうしょうがっこうこうどうけんこうかいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷2191","lat":33.14201834,"lng":129.90762081,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積974㎡","structure_material":"木造平屋一部2階建","registered":"2010.01.15(平成22.01.15)","register_no":"42-0088","desc":"旧校庭の東端に建ち、建築面積９７４㎡、木造平屋一部２階建、屋根は東西を半切妻とし、セメント瓦を葺く。南北面に下屋を付け、外壁は下見板張とする。正面はペディメント付の玄関ポーチを設け、２階にベイウィンドゥ付の切妻屋根を張り出すなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008074"},{"id":"00006439","register_sub_id":"101","register_pk":"107422","name":"長崎大学(旧長崎高等商業学校）拱橋","kana":"ながさきだいがく（きゅうながさきこうとうしょうぎょうがっこう）こまねきばし","category":"学校","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市片淵4-2-1","lat":32.758881,"lng":129.887405,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造単アーチ橋、橋長17m、幅員9.1m","structure_material":"石造単アーチ橋","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0069","desc":"長崎大学経済学部構内の西側を南北に流れる西山川に架かる。橋長１７ｍ、幅員９．１ｍの石造単アーチ橋。表面を平滑に仕上げた切石で欠円アーチをつくり、路面縦断面線形を直線状とするなど、近代的な外観を呈する。旧長崎高等商業学校創立当初から残る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006439"},{"id":"00006441","register_sub_id":"101","register_pk":"107424","name":"長崎大学経済学部倉庫（旧長崎高等商業学校倉庫）","kana":"ながさきだいがくけいざいがくぶそうこ（きゅうながさきこうとうしょうぎょうがっこうそうこ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市片淵4-2-1","lat":32.759724,"lng":129.88768,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積64㎡","structure_material":"煉瓦造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"42 － 0067","desc":"長崎大学経済学部構内の西側に位置する。桁行９．０ｍ、梁間７．１ｍ規模の切妻造、桟瓦葺、妻入の煉瓦造２階建で、東面して建つ。基礎を花崗岩布積、壁面をイギリス積で築き、四周に縦長窓を配する。旧長崎高等商業学校の創立当初から残る唯一の建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006441"},{"id":"00006440","register_sub_id":"101","register_pk":"107423","name":"長崎大学瓊林会館（旧長崎高等商業学校研究館）","kana":"ながさきだいがくけいりんかいかん（きゅうながさきこうとうしょうぎょうがっこうけんきゅうかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県長崎市片淵4-2-1","lat":32.758743,"lng":129.88858,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、スレート葺、建築面積258㎡、車寄付","structure_material":"煉瓦造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"42 － 0066","desc":"長崎大学経済学部構内の東側に位置する。桁行２２ｍ、梁間１２ｍ規模の寄棟造、スレート葺、平入の煉瓦造２階建で、西面して建つ。モルタル塗のゲーブル及び車寄を中心として縦長上下窓を四周に配した左右対称のつくりで、随所にセセッション風の装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006440"},{"id":"00000109","register_sub_id":"101","register_pk":"101099","name":"九州学院高等学校講堂兼礼拝堂","kana":"きゅうしゅうがくいんこうとうがっこうこうどうけんれいはいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市大江５-2-1","lat":32.79815841,"lng":130.72306627,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積525㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"43 － 0002","desc":"学校の設立者ブラウンを記念して建設された。教会と同様の三身廊式の平面を持ち，白い人造石の柱型と黒モルタルの壁を対比させた正面の意匠に特徴がある。我が国に多数の作品を残した米国人宣教師ヴォーリズの設計で，その作風の一端を示す好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000109"},{"id":"00000176","register_sub_id":"101","register_pk":"101166","name":"九州女学院高等学校本館","kana":"きゅうしゅうじょがくいんこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市黒髪3-12-16","lat":32.81974948,"lng":130.72293102,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上2階（一部3階）地下1階建，建築面積1131㎡","structure_material":"鉄筋コンクリート造地上2階（一部3階）地下1階建","registered":"1997.05.07(平成9.05.07)","register_no":"43 － 0003","desc":"ミッション・スクールの本館で，小高い丘の上に立つＲＣ造の校舎である。設計は米人の建築家ヴォーゲル。正面の一段高い列柱と巨大な日本瓦の切妻屋根が特徴で，当時の学校建築等が洋風を基調としている中で細部まで和風の装いを保っている点は興味深い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000176"},{"id":"00009244","register_sub_id":"101","register_pk":"164797","name":"京都大学理学研究科附属地球熱学研究施設火山研究センター（旧京都帝国大学阿蘇火山研究所）本館","kana":"きょうとだいがくりがくけんきゅうかふぞくちきゅうねつがくけんきゅうしせつかざんけんきゅうせんたー（きゅうきょうとていこくだいがくあそかざんけんきゅうじょ）ほんかん","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県阿蘇郡南阿蘇村河陽5280","lat":32.88547655,"lng":131.00656367,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造6階建、建築面積681㎡","structure_material":"鉄筋コンクリート造6階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"阿蘇山麓に建つ火山に関する研究や教育のための施設である。鉄筋コンクリート造、建築面積681平方メートルで、中央部を6階建の塔状とする。傾斜した外壁や異様に太い円柱など、随所に特異な意匠を用いる。昭和初期における日本建築界の様相の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009244"},{"id":"00002324","register_sub_id":"101","register_pk":"103314","name":"熊本県立玉名高等学校正門","kana":"くまもとけんりつたまなこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県玉名市中1853","lat":32.929993,"lng":130.548538,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、間口5m、左右脇門及び袖塀付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"43 － 0048","desc":"ＪＲ鹿児島本線玉名駅から北へ向かう駅前通りの突き当たりに位置する。道路より退いて間口５ｍの門を開き，両脇塀にアーチ形の通用口を開ける。通用口上部に起り形のカーブをつけ，末端部は楠木を囲うように曲面状にするなど流動感のある造形に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002324"},{"id":"00002322","register_sub_id":"101","register_pk":"103312","name":"熊本県立玉名高等学校本館","kana":"くまもとけんりつたまなこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県玉名市中1853","lat":32.93063309,"lng":130.54879339,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積671㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.08.28(平成13.08.28)","register_no":"43 － 0046","desc":"旧制玉名中学校本館として建設。鉄筋コンクリート造３階建のアールデコ建築で，正面東端寄りの時計塔頂部及び正面中央の玄関車寄部とその上部に装飾を効果的に集中させるデザインでまとめる。設計担当は名高工出身で熊本県学校営繕技師の近藤良馬。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002322"},{"id":"00002323","register_sub_id":"101","register_pk":"103313","name":"熊本県立玉名高等学校前庭池","kana":"くまもとけんりつたまなこうとうがっこうまえにわいけ","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県玉名市中1853","lat":32.93036844,"lng":130.54845974,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"コンクリート造、面積367㎡","structure_material":"コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"43 － 0047","desc":"本館の南前庭に位置するコンクリート造，笠石付きの池で，水深約１ｍ，周長約５０ｍの半円形２池から成る。２池の間に通路を通しており，上から見ると「中」の字の形になる。３棟の校舎の玉字形配置に呼応して「玉中」を表現したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002323"},{"id":"00000748","register_sub_id":"101","register_pk":"101738","name":"熊本大学医学部山崎記念館（旧熊本医科大学図書館）","kana":"くまもとだいがくいがくぶやまざききねんかん（きゅうくまもといかだいがくとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市本荘1-1-1","lat":32.79571569,"lng":130.71074758,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積446㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0012","desc":"熊本医科大学長兼教授山崎正董博士を記念した建物で，武田五一の設計になる。鉄筋コンクリート造２階建の図書館建築。２階開口部方立のデザインに特徴がある。箱形マッスの構成で建築形態をつくり，水平帯の意匠により全体に統一感を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000748"},{"id":"00000747","register_sub_id":"101","register_pk":"101737","name":"熊本大学本部（旧熊本高等工業学校本館）","kana":"くまもとだいがくほんぶ（きゅうくまもとこうとうこうぎょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市黒髪2-39-1","lat":32.81384557,"lng":130.72783116,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1038㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0011","desc":"創立時木造校舎の焼失後の再建校舎で，文部省直轄学校における鉄筋コンクリート造校舎の初期のものになる。設計担当は文部技師の長岡勇衛。柱型とセセッション風の柱頭飾りなどに鉄筋コンクリート建築に対する取組の跡がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000747"},{"id":"00005211","register_sub_id":"101","register_pk":"106201","name":"熊本ルーテル学園神水幼稚園園舎","kana":"くまもとるーてるがくえんくわみずようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市神水1-633-2","lat":32.78462917,"lng":130.74123321,"geo_status":"db","era":"昭和4／昭和9頃・昭和40増改築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積341㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"43 － 0077","desc":"水前寺公園から南東に位置する敷地に東面して建つ。桁行２７ｍの切妻造，桟瓦葺で，玄関を中心として左右に張出部を設ける。開口部を広くとる，採光と換気に配慮したつくり。半円アーチ窓に対応させてむくりをつけた玄関の切妻屋根のおさまりが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005211"},{"id":"00000231","register_sub_id":"101","register_pk":"101221","name":"京都大学理学部附属地球熱学研究施設","kana":"きょうとだいがくりがくぶふぞくちきゅうねつがくけんきゅうしせつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県別府市野口原3088-176","lat":33.284288,"lng":131.48568878,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造地上2階地下1階建棟屋付，建築面積510㎡","structure_material":"煉瓦造地上2階地下1階建棟屋付","registered":"1997.06.12(平成9.06.12)","register_no":"44 － 0006","desc":"中央部に塔屋を持つ煉瓦造の研究施設。平面はＬ字型である。設計は京大施設部の永瀬狂三。煉瓦の赤と石貼りの白との対照や、イオニア式を模した柱頭飾りを持つ特徴的な外観で、別府湾を見おろすシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000231"},{"id":"00012078","register_sub_id":"101","register_pk":"211019","name":"高原町民体育館分館","kana":"たかはるちょうみんたいいくかんぶんかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県西諸県郡高原町大字西麓338-2","lat":31.9281,"lng":131.007083,"geo_status":"db","era":"昭和11年／昭和40年代改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積980㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"45-90","desc":"高原小学校講堂として建てられた規模の大きな講堂。建築面積九八〇平方メートルで、建ちが高く、柱形を見せる洋風外観が特徴的。外部両側面には当初よりバットレスを取り、内部は当初はバルコニーを巡らしていた。地域の歴史的景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012078"},{"id":"00012268","register_sub_id":"101","register_pk":"353069","name":"綾陽校記念館","kana":"りょうようこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県東諸県郡綾町大字北俣1012","lat":32.004241,"lng":131.248717,"geo_status":"db","era":"明治21年／昭和32年・同53年・同60年移築、昭和53年増築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"45-94","desc":"綾小学校校舎として建築され、三度の移築を経て現在地に移されたもの。桁行二七メートルに及ぶ寄棟造桟瓦葺。外壁簓子下見板張、内部漆喰壁とし、西側に廊下を通し、東側に教室３室を並べる構成をとる。当時の標準的な小学校校舎の有様をよく示す建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012268"},{"id":"00005692","register_sub_id":"101","register_pk":"106680","name":"池地小中学校旧奉安殿","kana":"いけじしょうちゅうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町池地","lat":28.02990182,"lng":129.239258,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.2㎡、基壇及び柵付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0028","desc":"校庭側を向いて西面して建つ。御真影と教育勅語を奉安していた。下に柵付の基壇，上には平高欄付の基壇を築く。鉄筋コンクリート造，切妻造，平入で，四隅に角柱を型取り，軒は一軒疎垂木とし，棟には千木，堅男木をつける。神社建築を範とした奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005692"},{"id":"00006663","register_sub_id":"101","register_pk":"107646","name":"今里小中学校旧奉安殿","kana":"いまざとしょうちゅうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡大和村今里字クツレ361-1","lat":28.326511,"lng":129.278366,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.5㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0059","desc":"敷地の最奥、山裾に北面して建つ。切妻造平入の鉄筋コンクリート造で、正面に戸口を開け、周囲に組高欄を廻す。方柱で、組物はなく、一軒疎垂木とし、妻には懸魚を付ける。建築当初位置に残り、基壇を２段に造り、正面に石段７級を設け、威厳のある外貌を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006663"},{"id":"00004194","register_sub_id":"101","register_pk":"105184","name":"鹿児島県立鹿児島工業高等学校大煙突","kana":"かごしまけんりつかごしまこうぎょうこうとうがっこうだいえんとつ","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市草牟田2-57-1","lat":31.60855194,"lng":130.53835522,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造、高さ18m、ボイラー付","structure_material":"煉瓦造","registered":"2004.06.09(平成16.06.09)","register_no":"46 － 0015","desc":"機械科で使用する工作機械を稼働させるためのスチームボイラーとともに建設。高さ１８ｍの煉瓦造煙突で，八角形の基部をイギリス積，塔身を小口積として構築する。径１．２ｍ長４．５ｍの鉄製ボイラーとともに学校や地域の景観に欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004194"},{"id":"00006293","register_sub_id":"101","register_pk":"107276","name":"鹿児島県立鹿児島中央高等学校本館及び講堂","kana":"かごしまけんりつかごしまちゅうおうこうとうがっこうほんかんおよびこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市加治屋町10-1","lat":31.586428,"lng":130.54985,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積2866㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0038","desc":"敷地西側に建つ。ＲＣ造３階一部４階建で，平面はロの字形で，南北５５ｍ，東西７７ｍ，幅１１ｍの規模とする。南東に講堂を置き，北西隅を曲面でつくり正面玄関とし，上部アーチ状の縦型窓を開き，円形平面の４階部分をつくるなど，ＲＣ造の特徴を活かす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006293"},{"id":"00006292","register_sub_id":"101","register_pk":"107275","name":"鹿児島県立甲南高等学校本館","kana":"かごしまけんりつこうなんこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市上之園町23-1","lat":31.57931987,"lng":130.54649656,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2412㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0037","desc":"敷地北側及び東側に寄って建つ。鉄筋コンクリート造３階建で，平面はＬ字形で，幅１０ｍ，北側長さ１１２ｍ，東側長さ８２ｍの規模とする。北東隅の曲面部に正面玄関を置き，上部はドーム状の塔屋とする。初期のＲＣ造の学校建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006292"},{"id":"00005775","register_sub_id":"101","register_pk":"106763","name":"鹿児島大学総合研究博物館常設展示室","kana":"かごしまだいがくそうごうけんきゅうはくぶつかんじょうせつてんじしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市郡元1-21-24","lat":31.57162985,"lng":130.54604416,"geo_status":"db","era":"昭和3／平成15改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積105㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"46 － 0032","desc":"敷地の北東方に位置し，北面して建つ。間口１１ｍ，奥行９ｍ，鉄筋コンクリート造２階建とする。前身の鹿児島高等農林学校の図書館書庫として建てられた建物で，学校建築における初期の鉄筋コンクリート建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005775"},{"id":"00007706","register_sub_id":"101","register_pk":"108688","name":"川上中学校本校舎","kana":"かわかみちゅうがっこうほんこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"鹿児島県","address":"鹿児島県肝属郡肝付町後田6339-23","lat":31.28424734,"lng":130.9507361,"geo_status":"db","era":"昭和24／昭和36・昭和47改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積331㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"46 － 0081","desc":"校地の東寄りに南北棟で建つ。切妻造桟瓦葺で、外壁を下見板張とし、東・西面各４ヶ所にバットレスを付ける。運動場側の西側を廊下とし、当初は中央南寄りを土間床の通路とし、北に３教室、南に職員室を配した。山間に残る木造校舎で、風情ある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007706"},{"id":"00007147","register_sub_id":"101","register_pk":"108129","name":"旧鹿児島県立尋常中学校門","kana":"きゅうかごしまけんりつじんじょうちゅうがっこうもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町14-1","lat":31.5997441,"lng":130.5572479,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造門柱2基、間口3.1m、両側通用門付","structure_material":"石造門柱2基","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0064","desc":"旧県庁舎敷地西辺中央に位置する。鹿児島県立尋常中学校創設時の正門で、間口３．１ｍ、本柱の高さ２．３ｍ、脇柱の高さ２．２ｍの規模をもつ洋風石造門。県立尋常中学校正門、県立図書館正門、県庁舎裏門として使用され、旧県庁舎敷地の変遷を見続けてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007147"},{"id":"00005695","register_sub_id":"101","register_pk":"106683","name":"旧木慈小学校奉安殿","kana":"きゅうきじしょうがっこうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町木慈","lat":28.16023791,"lng":129.21902529,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積3.7㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0031","desc":"旧校内に西面して建ち，御真影と教育勅語を奉安していた。高欄付の基壇上にあり，鉄筋コンクリート造，切妻造，平入で，軒は一軒疎垂木，破風に懸魚，棟に千木と堅男木をつける。四隅に角柱を型取り，壁面は洗い出し仕上げとする。神社建築を範とした奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005695"},{"id":"00014127","register_sub_id":"101","register_pk":"508387","name":"旧山尋常高等小学校校舎","kana":"きゅうさんじんじょうしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡徳之島町山字兼久田1808-イ","lat":27.86682778,"lng":128.95683333,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積65㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"46 - 0127","desc":"徳之島北東部に位置し、敷地奥に南面して建つ。鉄筋コンクリート造二階建。外観は隅の柱型を見せ、入口に庇を付し、壁面は等間隔に横目地を切る。内部は前面に玄関や階段室を配し、一、二階とも奥を教室とする。島内現存最古の鉄筋コンクリート造学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014127"},{"id":"00005690","register_sub_id":"101","register_pk":"106678","name":"古仁屋小学校旧奉安殿","kana":"こにやしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町古仁屋小勝原","lat":28.15006225,"lng":129.31444903,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積6.0㎡、柵付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0026","desc":"御真影と教育勅語を奉安していた。鉄筋コンクリート造で，四隅に角柱を型取り，上部にコーニスを廻し，陸屋根で正背面にペディメント風の飾りをつける。洋風建築細部を備え，堅牢で風格あるつくりである。一段低い校庭側に西面して建ち，今なお存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005690"},{"id":"00005693","register_sub_id":"101","register_pk":"106681","name":"薩川小学校旧奉安殿","kana":"さつかわしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町薩川","lat":28.18034901,"lng":129.20320043,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積3.5㎡、基壇及び柵付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0029","desc":"校内南東隅に西面して建ち，御真影と教育勅語を奉安していた。下に柵付の基壇，上に刎高欄付の基壇を築く。鉄筋コンクリート造，切妻造，平入で，四隅に角柱を型取り，内法長押を廻し，軒は一軒疎垂木とする。神社建築を範とした奉安殿で，良好な状態を保つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005693"},{"id":"00014444","register_sub_id":"101","register_pk":"511433","name":"山小学校校舎","kana":"さんしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"鹿児島県","address":"鹿児島県大島郡徳之島町山1808-イ","lat":27.86695,"lng":128.95671667,"geo_status":"db","era":"昭和30年／同44年増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積334㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"46 - 0128","desc":"徳之島北東部に所在する校舎。鉄筋コンクリート造二階建、各階北側に教室を二室並べ、南側は開放廊下とし、西端に階段室を付す。後年更に西側に各階一室増築。平面等が米国民政府工務交通局の二階建４教室標準設計に共通し、正面の開放廊下が印象的な校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014444"},{"id":"00006562","register_sub_id":"101","register_pk":"107545","name":"鹿浦小学校旧奉安殿","kana":"しかうらしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡伊仙町阿三字為の当2206-5","lat":27.69112015,"lng":128.91987461,"geo_status":"db","era":"昭和13頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.3㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0045","desc":"学校敷地の東端に建つ。間口２．２ｍ，奥行１．９ｍの規模で，鉄筋コンクリート造平屋建とする。石造の基壇の上に建ち，切妻屋根正面に柱２本を立て，向拝唐破風の屋根を付けた形式とし，四隅に円柱の柱形や長押形を造り出し，伝統的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006562"},{"id":"00005694","register_sub_id":"101","register_pk":"106682","name":"須子茂小学校旧奉安殿","kana":"すこもしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町須子茂","lat":28.147732,"lng":129.210541,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.2㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0030","desc":"校内北東部に西面して建ち，御真影と教育勅語を奉安していた。刎高欄付の基壇上にあり，鉄筋コンクリート造，切妻造，平入で，軒は一軒疎垂木，棟に千木と堅男木をつける。四隅に角柱を型取り，壁面は洗い出し仕上げとする。神社建築を範とした奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005694"},{"id":"00005691","register_sub_id":"101","register_pk":"106679","name":"節子小中学校旧奉安殿","kana":"せつこしょうちゅうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町節子","lat":28.16591834,"lng":129.38298706,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.6㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0027","desc":"校庭側を向いて西面してあり，御真影と教育勅語を奉安していた。鉄筋コンクリート造で，高欄を廻した壇正積風の基壇上に建つ。切妻造，平入の形式で，四隅に円柱を型取り，内法長押を廻し，桁を受け，軒は一軒疎垂木を型取る。神社建築を範とした奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005691"},{"id":"00005696","register_sub_id":"101","register_pk":"106684","name":"旧国頭農学校玄関","kana":"きゅうくにがみのうがっこうげんかん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県名護市字宇茂佐13","lat":26.595928,"lng":127.96312,"geo_status":"db","era":"明治35／昭和40移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、面積9.4㎡","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"47 － 0017","desc":"唐破風造の吹放ち玄関で，正面柱間３．６ｍ。琉球赤瓦葺とする。角柱上の組物は大斗，実肘木で，虹梁を受け，板蟇股と斗，実肘木で棟木を受ける。破風は拝みと起りの中程に茨をつけ，拝懸魚を飾り，竿縁天井とする。沖縄における伝統意匠の数少ない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005696"},{"id":"00013014","register_sub_id":"101","register_pk":"368327","name":"網走市立郷土博物館新館","kana":"あばしりしりつきょうどはくぶつかんしんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道網走市桂町一丁目1","lat":44.01776667,"lng":144.26910556,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造及び鉄筋コンクリート造地上2階地下1階建、金属板葺、建築面積138㎡","structure_material":"木造及び鉄筋コンクリート造地上2階地下1階建","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0157","desc":"昭和11年に開館した郷土博物館の新館として本館東側に増築した。設計は本館同様田上義也による。木造2階建、地階付とし、矩形平面で屋根は片流れとする。立面は本館との連続性を考慮しつつ、壁面の切込などの彫塑的表現に、田上の戦後の作風を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013014"},{"id":"00013013","register_sub_id":"101","register_pk":"368326","name":"網走市立郷土博物館本館","kana":"あばしりしりつきょうどはくぶつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道網走市桂町一丁目1","lat":44.01774167,"lng":144.26888611,"geo_status":"db","era":"昭和11年／昭和60年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、金属板葺、建築面積197㎡、塔屋付","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0156","desc":"市街南部の丘陵に南面して建つ、道内最初期の郷土博物館。塔屋付木造二階建、左右対称平面の中央を南北に張出し、正面にアーチをみせる。外壁は鉄網コンクリート塗、胴部は左官仕上で幾何学模様のパネルを貼る。建築家田上義也による独創的な意匠の文化施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013013"},{"id":"00002109","register_sub_id":"101","register_pk":"103099","name":"函館中華会館","kana":"はこだてちゅうかかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市大町1-20","lat":41.76806457,"lng":140.709457,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積374㎡","structure_material":"煉瓦造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"01 － 0028","desc":"関帝を祀る主棟と，左右前方に延びた翼廊，これを閉じる正面玄関棟からなる。日本に現存する唯一の関帝廟形式の集会所で，内部は華麗で爛熟した清朝末期の雰囲気を持つ。明治４０年の函館大火後に建てられた煉瓦造建築で，地域の景観のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002109"},{"id":"00014704","register_sub_id":"101","register_pk":"518962","name":"ヒノキ新薬株式会社ルスツ山寮","kana":"ひのきしんやくかぶしきかいしゃるすつさんりょう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和後","pref":"北海道","address":"北海道虻田郡留寿都村字泉川645他","lat":42.75938333,"lng":140.92279722,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、鉄板葺、建築面積812㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"01 - 0169","desc":"尻別岳山麓に位置する企業の保養所。設計は白井晟一。長大な二階建に緩勾配の切妻造屋根を架け、外壁に濃淡に富む煉瓦積・石積を用いた独特な外観。内部吹抜には、片持で薄く仕上げた踊場付階段など要所に彫塑的造形を配す。白井による北海道唯一の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014704"},{"id":"00010714","register_sub_id":"101","register_pk":"201549","name":"北海道護国神社平成館（旧陸軍第七師団北鎮兵事記念館）","kana":"ほっかいどうごこくじんじゃへいせいかん（きゅうりくぐんだいしちしだんほくちんへいじきねんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道旭川市花咲町一丁目3853他","lat":43.786841,"lng":142.366389,"geo_status":"db","era":"昭和10／平成2改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階地下１階建、鉄板葺、建築面積360㎡","structure_material":"鉄筋コンクリート造平屋一部2階地下１階建","registered":"2015.11.17(平成27.11.17)","register_no":"01 ‐ 0145","desc":"神社境内の南東に建つ、鉄筋コンクリート造一部二階地下一階建。中央部の正背面を張出し、切妻造の屋根も中央を高めて強調する。屋根の大棟や降棟に鬼を置き、破風に懸魚を飾る。白壁の腰を石張として城郭風に見せるなど、当時の日本趣味意匠の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010714"},{"id":"00014219","register_sub_id":"101","register_pk":"509609","name":"北海道大学空沼小屋","kana":"ほっかいどうだいがくそらぬまこや","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道札幌市南区常盤石狩森林管理署1157イ林小班","lat":42.88033611,"lng":141.26025278,"geo_status":"db","era":"昭和3年／平成28年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積56㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"01 - 0162","desc":"空沼岳の万計沼畔に所在する山小屋で、秩父宮雍仁親王の発意により、スイス人建築家ヒンデルが設計した。丸太組構法二階建、小規模ながら機能的な設計で最大30名宿泊可能。金具意匠、木柄太さ、ストーブ廻りの吹抜等、スイスの良質な山小屋を思わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014219"},{"id":"00008803","register_sub_id":"101","register_pk":"162246","name":"夕張鹿鳴館(旧北炭鹿ノ谷倶楽部)","kana":"ゆうばりろくめいかん（きゅうほくたんしかのたにくらぶ）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道夕張市鹿の谷2-4-1","lat":43.03707729,"lng":141.96024781,"geo_status":"db","era":"大正2年／大正5年増築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1609㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"01 － 0112","desc":"北面して玄関を構える木造平屋建で、建築面積1609㎡に及ぶ。中央に本館、西に第一別館、東に第二別館を配し、廊下で繋ぐ。本館は諸室を雁行型に配し、寄棟や切妻の屋根を複雑に連続させ、下屋庇をまわし、深い陰影を見せる。倶楽部建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008803"},{"id":"00005729","register_sub_id":"101","register_pk":"106717","name":"岩手県公会堂","kana":"いわてけんこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市内丸11-2","lat":39.70316799,"lng":141.15348399,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積1580㎡、塔屋付","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"03 － 0061","desc":"敷地中央にほぼ南面して建つ。間口４４ｍ，奥行４８ｍの規模で，ＲＣ造２階建，陸屋根とする。玄関奥を階段室，その奥を中庭とし，後部に大ホールを置く。中央に６層の塔屋を設け，外壁をスクラッチタイル貼とし，外部に柱形を現して垂直性を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005729"},{"id":"00011434","register_sub_id":"101","register_pk":"210405","name":"旧遠野寶物館（遠野市立博物館新町収蔵庫）","kana":"きゅうとおのほうもつかん（とおのしりつはくぶつかんしんまちしゅうぞうこ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県遠野市新町230-2","lat":39.32901,"lng":141.526599,"geo_status":"db","era":"大正14年／昭和24年・同55年頃改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積96㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"03-0088","desc":"遠野市街地の中心に建つ。耐震耐火を考慮し、鉄筋コンクリート造とする。外壁は、窓廻りを窪ませるなどの幾何学的意匠が特徴で、内部は一、二階とも一室で、側柱のみで支える無柱の大空間とする。遠野地方における最初の鉄筋コンクリート造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011434"},{"id":"00013017","register_sub_id":"101","register_pk":"368224","name":"後藤伯記念公民館","kana":"ごとうはくきねんこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県奥州市水沢大手町四丁目1","lat":39.14486944,"lng":141.14016389,"geo_status":"db","era":"昭和16年／昭和32年増築、同62年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積947㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"03 － 0110","desc":"水沢の旧城下中心部にある公民館。敷地西辺に南北棟で建つ本館と、南東側の柔剣道場を逆Ｌ字形の建物で繋ぐ。本館南寄りを大きな切妻屋根として妻壁をハーフティンバー風に飾り、前面に切妻屋根の車寄を突出する。大小の切妻屋根が重層した風格あるつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013017"},{"id":"00013910","register_sub_id":"101","register_pk":"508170","name":"齋藤子爵水沢文庫図書閲覧所","kana":"さいとうししゃくみずさわぶんことしょえつらんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県奥州市水沢字吉小路24イ","lat":39.14429167,"lng":141.13471111,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"03 - 0112","desc":"図書庫の東に渡廊下で隣接する木造平屋建桟瓦葺、水回りなど自邸としての設備も有する閲覧所。寄棟造の屋根を雁行に重ね、南西に入母屋造玄関が付く。内部は洋間のほか、続き間座敷の南にガラス窓を連ねる閲覧室を設け、郷土の子弟への供用を目的とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013910"},{"id":"00013909","register_sub_id":"101","register_pk":"508169","name":"齋藤子爵水沢文庫図書庫","kana":"さいとうししゃくみずさわぶんことしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県奥州市水沢字吉小路24イ","lat":39.14485,"lng":141.13464722,"geo_status":"db","era":"昭和7年／同10年増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積102㎡","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"03 - 0111","desc":"第三〇代総理大臣斎藤實が水沢城下生家跡に建てた私設図書館。鉄骨鉄筋コンクリート造二階建、陸屋根、外壁をイギリス積風煉瓦張、腰は石貼。内部は一階入口に受付カウンターを配し、他は書庫で階段手摺や金具に真鍮を用いる。海軍技師の設計による建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013909"},{"id":"00009257","register_sub_id":"101","register_pk":"194050","name":"旧相川診療所","kana":"きゅうあいかわしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"宮城県","address":"宮城県石巻市北上町十三浜字崎山152-3","lat":38.60727696,"lng":141.50077518,"geo_status":"db","era":"昭和36年／平成23年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋一部2階建、スレート葺、建築面積166㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"04 － 0088","desc":"石巻市北東端の相川集落内に建つ。木造平屋建の診療所と同二階建の休憩所をＬ形に接続する。外壁は下見板張で診療所はペンキ塗とし、屋根は両者とも切妻造スレート葺である。病院のへき地出張所としての形態を伝えるとともに、スレート葺が地域的特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009257"},{"id":"00013922","register_sub_id":"101","register_pk":"508182","name":"竹駒神社馬事博物館","kana":"たけこまじんじゃばじはくぶつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県岩沼市稲荷町4-1","lat":38.10478056,"lng":140.86393056,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0210","desc":"竹駒神社境内に位置。基礎及び床を鉄筋コンクリート造、上部を木造とした平屋建寄棟造銅板葺。切妻造の車寄玄関を付し、鴟尾、懸魚、蟇股等、和風の細部意匠を持つ。展示室は壁及び天井を漆喰塗、腰をタイル貼とする。日本趣味が横溢する馬専門博物館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013922"},{"id":"00016478","register_sub_id":"101","register_pk":"574840","name":"大潟村公民館","kana":"おおがたむらこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和後","pref":"秋田県","address":"秋田県南秋田郡大潟村字中央1-21","lat":40.01771111,"lng":139.95990806,"geo_status":"db","era":"昭和44年","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"鉄筋コンクリート造2階一部6階建、建築面積645㎡","structure_material":"鉄筋コンクリート造2階一部6階建","registered":"2026.02.10(令和8.02.10)","register_no":"05 - 0261","desc":"大潟村の中心部に位置する公民館。鉄筋コンクリート造２階建切妻造の東西棟で、西側の６階建展望塔と渡廊下で接続する。内部は中廊下の南北に大小の集会室を配し、中央階段の上部に天窓を開ける。計画都市の軸線上に建つ公民館で、地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016478"},{"id":"00012092","register_sub_id":"101","register_pk":"352891","name":"旧大倉沢報徳館","kana":"きゅうおおくらざわほうとくかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市大倉沢字大沢16-2","lat":39.437378,"lng":140.143784,"geo_status":"db","era":"昭和5年頃／平成15年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"05-217","desc":"木造平屋建、寄棟造桟瓦葺で、内部は鴨居上を高く取り、平面は玄関奥の廊下を矩折れに延ばし、大広間四二畳、応接室八畳、小会議所一二畳等を配す。細部に洋風意匠を配し、外壁は下見板張に窓上モルタル搔き落しとする。報徳社の支社社屋の数少ない遺存例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012092"},{"id":"00007835","register_sub_id":"101","register_pk":"108816","name":"旧杏華堂石田医院座敷蔵","kana":"きゅうきょうかどういしだいいんざしきぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字上町56他","lat":39.20155204,"lng":140.54621337,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05-0170","desc":"敷地のほぼ中央に建つ。南北棟の切妻造鉄板葺、桁行９．１ｍ梁間５．５ｍ、土蔵造２階建。北妻に入口を穿ち、掛子塗四段の両開扉を吊る。内部仕上げや座敷飾りなどに伝統を踏襲しつつ、キングポストトラス組や階段高欄等に新たな技法や洋風の意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007835"},{"id":"00003346","register_sub_id":"101","register_pk":"104336","name":"旧小坂鉱山病院記念棟","kana":"きゅうこさかこうざんびょういんきねんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県鹿角郡小坂町小坂鉱山字古舘48-2","lat":40.3284678,"lng":140.74471737,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"05 － 0093","desc":"旧小坂鉱山病院の霊安施設。西正面中央部に出入口を開き，２間四方の霊安室を取り，その北に踏込土間を備えた３畳敷の和室を配する。出入口にはペディメント付きのポーチを備え，各上げ下げ窓には繊細な蛇腹の庇を付けるなど，小規模ながら瀟洒な意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003346"},{"id":"00003345","register_sub_id":"101","register_pk":"104335","name":"天使館（旧聖園マリア園）","kana":"てんしかん（きゅうせいえんまりあえん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県鹿角郡小坂町小坂鉱山字古舘35-6","lat":40.3285642,"lng":140.74354433,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積372㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"05 － 0092","desc":"小坂鉱山従業員のための幼児教育施設。木造平屋建で，町の中心を南北に通る町道に東面して建つ。ドイツ下見の外壁（西背面のみイギリス下見），縦長の上げ下げ窓，玄関ポーチの柱型やペディメント，大屋根端部やポーチ上部の棟飾等，平明な洋風の意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003345"},{"id":"00009894","register_sub_id":"101","register_pk":"196041","name":"朝日座","kana":"あさひざ","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県南相馬市原町区大町1-120","lat":37.63901969,"lng":140.96060271,"geo_status":"db","era":"大正12／昭和30頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積508㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"07 － 0149","desc":"通り沿いの敷地奥に西面して建つ映画館。木造二階建、外壁モルタル塗で、正面にはコーニス上にペディメントとフィニアルを飾る。内部には芝居小屋当時の桟敷席などを残す。地域の娯楽の殿堂として長く親しまれ、芝居小屋から映画館へ至る改修の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009894"},{"id":"00006290","register_sub_id":"101","register_pk":"107273","name":"旧大越娯楽場","kana":"きゅうおおごえごらくじょう","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県田村市大越町上大越字町1","lat":37.38306,"lng":140.630569,"geo_status":"db","era":"大正15／昭和30頃改造","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積466㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"07 － 0082","desc":"集落内の交差点に建つ。建築面積４６６㎡，木造２階建，鉄板葺。正面を入母屋形式として両側に塔屋を建てる芝居小屋風の構成とするが，外壁をモルタル塗として軒下にはデンティルを現し，窓上部を鎧戸風にして洋風の外観を呈する。村民のための娯楽施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006290"},{"id":"00014229","register_sub_id":"101","register_pk":"509619","name":"旧三宮堂田中医院診療所","kana":"きゅうさんのみやどうたなかいいんしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県双葉郡双葉町大字長塚字町12","lat":37.45380833,"lng":141.00775,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"07 - 0272","desc":"双葉駅前の旧陸前浜街道沿いに所在する木造洋風医院建築。寄棟造、正面切妻破風、外壁モルタル掻落し、玄関ポーチを付して飾る。側背面は下見板張とする。一階は診療室など病院機能の諸室、二階は床付座敷と洋室を配す。町の象徴的な建物として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014229"},{"id":"00014230","register_sub_id":"101","register_pk":"509620","name":"旧三宮堂田中医院煉瓦蔵","kana":"きゅうさんのみやどうたなかいいんれんがぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県双葉郡双葉町大字長塚字町12","lat":37.45366944,"lng":141.00804167,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積19㎡","structure_material":"煉瓦造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"07 - 0273","desc":"診療所の背面側に建つ煉瓦造の小規模な倉庫。平屋建切妻造桟瓦葺妻入で、西面に入口を設けて鉄扉・格子戸を建て、掛庇を付して幾何学模様の持送金物で受ける。小屋は木造和小屋。壁はイギリス積で頂部に軒蛇腹を廻す。診療所とともに町の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014230"},{"id":"00002741","register_sub_id":"101","register_pk":"103731","name":"郡山市公会堂","kana":"こおりやましこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県郡山市麓山1-8-4","lat":37.394417,"lng":140.372284,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積1102㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"07 － 0064","desc":"郡山市制施行を記念して市中心部に建てられた。連続半円アーチの柱廊と，窓台受，上げ下げ連窓などを丁寧にデザインした躯体の隅に，縦長ガラス面で垂直性を強調した塔屋を設ける。開拓の意気込みを壮麗に表現した本格的様式建築。設計は矢橋賢吉と荻原貞雄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002741"},{"id":"00013031","register_sub_id":"101","register_pk":"368341","name":"仙峡閣","kana":"せんきょうかく","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市大戸町大字上小塩字遅谷3084-3","lat":37.36436111,"lng":139.91824722,"geo_status":"db","era":"昭和13年／昭和30年移築","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、金属板葺、建築面積605㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0224","desc":"会津若松市南郊の芦ノ牧温泉にある、もと武徳殿を転用した温泉旅館。渓谷沿いの斜面に建ち、入母屋造の大屋根に千鳥破風を飾り、正面に構える雄大な車寄に社寺建築の細部意匠を採用し、武徳殿の定型をよく示す。大胆な転用の経緯と勇壮な外観をもつ旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013031"},{"id":"00008804","register_sub_id":"101","register_pk":"162247","name":"蟹仙洞展示館","kana":"かいせんどうてんじかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"山形県","address":"山形県上山市矢来4-299-7他","lat":38.14944561,"lng":140.27889121,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造一部木造2階建、スレート葺一部鉄板葺、建築面積154㎡","structure_material":"鉄筋コンクリート造一部木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0122","desc":"敷地北西隅に建つ。北側に、鉄筋コンクリート造2階建切妻造桟瓦葺の主棟を配し、主屋との間に木造一部2階建の附属棟を建てて両者を接続する。建築面積174㎡である。主棟は伝統的な土蔵の外観を踏襲し、附属棟は急勾配の切妻屋根が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008804"},{"id":"00000330","register_sub_id":"101","register_pk":"101320","name":"掬粹巧芸館日本館","kana":"きくすいこうげいかんにほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2908、2909、2910-3","lat":38.01364594,"lng":140.05098713,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"石造・土蔵造2階建塔屋付，建築面積109㎡","structure_material":"石造・土蔵造2階建塔屋付","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0018","desc":"隣接する高畠町で産出する高畠石による石造建築。かつては川西町内に多数存在したが，現存するものは少ない。１階正面はアーチで外部空間を取り込んでいる。内部はタイルを多用した洋風のアプローチと，純和風の座敷からなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000330"},{"id":"00000329","register_sub_id":"101","register_pk":"101319","name":"掬粹巧芸館本館","kana":"きくすいこうげいかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2911-5、6、8、9","lat":38.01389906,"lng":140.05215674,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造平屋建，鉄板葺，建築面積70㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0017","desc":"樽平酒造当主井上家の十代目が設立した陶磁器美術館とするための建築である。土蔵造平屋建で，ほぼ正方形の平面を持つ。壁面には高窓を配し，正面は左右対称の構成としている。当初より展示を主目的とした建築としては最初期の例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000329"},{"id":"00014134","register_sub_id":"101","register_pk":"508764","name":"旧梅津歯科医院裏門及び黒板塀","kana":"きゅううめつしかいいんうらもんおよびくろいたべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15591667,"lng":140.276275,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 木造、鉄板葺、間口1.9m 塀 木造、鉄板葺、総延長19m","structure_material":"門 木造","registered":"2022.02.17(令和4.02.17)","register_no":"06-0202","desc":"旧城下町の医家の裏門と板塀で、穀物蔵に連なり敷地背面側の外郭となる。裏門は切妻造鉄板葺、疎垂木の腕木門で、棟に鬼板を飾り、腕木に繰形を施し、引違板戸を建てる。板塀は竪板張で、鉄板葺の小屋根を備える。城下の小路の良好な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014134"},{"id":"00014132","register_sub_id":"101","register_pk":"508762","name":"旧梅津歯科医院穀物蔵","kana":"きゅううめつしかいいんこくもつぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15581667,"lng":140.27625556,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、鉄板葺、建築面積42㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0200","desc":"旧城下町の医家の土蔵で、裏門に連なり敷地背面側の外郭となる。二階建、切妻造鉄板葺平入、漆喰仕上鉢巻付、一階土間は一部を仕切り、二階は板敷とする。戸口に掛子塗の扉、窓に鉄扉を備え、いずれも鳥居枠を豪壮に塗上げ、城下小路の景観を整える穀物蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014132"},{"id":"00014131","register_sub_id":"101","register_pk":"508761","name":"旧梅津歯科医院座敷蔵","kana":"きゅううめつしかいいんざしきぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15588611,"lng":140.27646389,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0199","desc":"旧城下町の医家の土蔵。二階建、切妻造鉄板葺平入、漆喰仕上鉢巻付、池庭に面する蔵前は縁を通してガラス戸を建てる。戸口と窓に掛子塗扉を備え、一階は仏間と床付座敷の続き座敷で、二階は物置。牛梁とこれを支える曲梁は太く、雪国らしい豪壮な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014131"},{"id":"00014130","register_sub_id":"101","register_pk":"508760","name":"旧梅津歯科医院住居棟","kana":"きゅううめつしかいいんじゅうきょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県上山市十日町941","lat":38.15569722,"lng":140.27652222,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0198","desc":"旧城下町の医家の住居棟和館。診療棟洋館の西側に接続し、二階建、入母屋造鉄板葺で鬼板を棟に飾る。一階は南面する玄関、日常的な用途の続き座敷、台所からなる。二階は格天井の続き座敷で、眺望の効く開放的な造りとし、座敷蔵と好対照な接客空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014130"},{"id":"00014129","register_sub_id":"101","register_pk":"508759","name":"旧梅津歯科医院診療棟","kana":"きゅううめつしかいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県上山市十日町941","lat":38.15575,"lng":140.27665,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積76㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0197","desc":"旧城下町の医家の診療棟洋館。敷地中央東寄りに南面し、二階建、入母屋造鉄板葺フィニアル付、ペディメント風のポーチを突出する。一階に薬局、二階に診察室と技工室を配す。各階の待合等は畳敷だが、天井中心飾りや階段手摺等、全体に洋風意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014129"},{"id":"00014133","register_sub_id":"101","register_pk":"508763","name":"旧梅津歯科医院味噌蔵","kana":"きゅううめつしかいいんみそぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市十日町941","lat":38.15574444,"lng":140.27634444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"06-0201","desc":"旧城下町の医家の土蔵で、主屋背面側の敷地西辺に位置する。平屋建、切妻造鉄板葺平入、漆喰仕上で腰はモルタル仕上。和小屋で、内部は引違戸で南北二室に仕切り、北側は床を張り、高窓を設ける。戸口と窓には土戸を備える。屋敷後方の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014133"},{"id":"00000560","register_sub_id":"101","register_pk":"101550","name":"舞鶴橋","kana":"まいづるばし","category":"文化福祉","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市丸の内1-4-13","lat":37.90889611,"lng":140.10592594,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"石造アーチ橋，橋長５m，幅員７m","structure_material":"石造アーチ橋","registered":"1998.07.23(平成10.07.23)","register_no":"06 － 0028","desc":"米沢城祉の堀に架かる石造橋で，現在は上杉神社への参道となっている。径間に比して幅員が広く，凝灰岩の欄干を設け親柱に自然石の奇岩を配するのが特徴。単アーチ橋ではあるが，「めがね橋」の愛称で米沢市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000560"},{"id":"00003784","register_sub_id":"101","register_pk":"104774","name":"旧大谷公会堂","kana":"きゅうおおやこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市大谷町1271-2","lat":36.59408889,"lng":139.81772222,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造平屋建、スレート葺、建築面積209㎡","structure_material":"石造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0087","desc":"地元産大谷石を構造躯体に用いた公会堂建築。正面１０ｍ，奥行２２ｍ規模，客席部は切妻造で，小屋組はキングポストトラスとし，正面に軒上まで立ち上げた４本の装飾的付柱が特徴的なファサードをつくる。設計は，県内建築事務所の草分的存在である更田時蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003784"},{"id":"00008638","register_sub_id":"101","register_pk":"149359","name":"駒橋歯科医院診療所","kana":"こまはししかいいんしんりょうしょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県鹿沼市今宮町字西中町1608-2","lat":36.564672,"lng":139.7453385,"geo_status":"db","era":"大正後期／昭和40年頃改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0192","desc":"神社への参道に西面する。木造2階建、1階に診療室、2階に客間などを配する。切妻造桟瓦葺で、正面左右に切妻造の棟を突き出す。下見板張で矩形窓を大きく開け、西・南面には幾何学模様を飾る。ハーフティンバー風仕上げの妻壁が並び、町並みに潤いを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008638"},{"id":"00013947","register_sub_id":"101","register_pk":"508207","name":"山縣有朋記念館別館","kana":"やまがたありともきねんかんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県矢板市上伊佐野字一本木1022-344","lat":36.88725556,"lng":139.880275,"geo_status":"db","era":"昭和2年頃／平成元年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"09 - 0264","desc":"山縣有朋が拓いた農場に所在。二階建寄棟造桟瓦葺で南正面にドーマー窓を掲げる。パーゴラ付ポーチを設け、上下窓や両開窓を開ける。内部のリビングは出窓や暖炉を備え、壁は腰を木羽目板とし、天井は梁形を表す格式備えた洋室。広大な農場に建つ瀟洒な洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013947"},{"id":"00000123","register_sub_id":"101","register_pk":"101113","name":"桐生織物会館旧館","kana":"きりゅうおりものかいかんきゅうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町1184-4","lat":36.41292856,"lng":139.33668554,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建，瓦葺，建築面積833㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"10 － 0006","desc":"桐生織物協同組合の事務所として建築された木造２階の建物で，設計は群馬県土木課営繕係。外壁をスクラッチタイル張りとし，屋根は静緑色の瓦を葺くなど洋風の装いになる。整然とした配置の窓やなど，昭和期における生産管理関係の事務所の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000123"},{"id":"00007181","register_sub_id":"101","register_pk":"108163","name":"富岡市社会教育館玄関及び事務室棟","kana":"とみおかししゃかいきょういくかんげんかんおよびじむしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.255272,"lng":138.859726,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0260","desc":"高台に占める敷地のほぼ中央に南面して建つ。軒先を鉄板葺とする桟瓦葺の寄棟造で、東寄りに切妻造妻入の車寄、西寄りに二ノ口玄関を設ける。内部は北面に廊下、南側に事務室や館長室などを配する。車寄の緩やかな勾配の直線的な屋根が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007181"},{"id":"00007182","register_sub_id":"101","register_pk":"108164","name":"富岡市社会教育館講師室棟","kana":"とみおかししゃかいきょういくかんこうししつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.2553931,"lng":138.85982903,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0261","desc":"玄関及び事務室棟の東北に雁行型に取り付く。軒鉄板葺の寄棟造桟瓦葺で、東西棟とする。十五畳の主室と十畳の次の間を東西に並べ、畳敷と榑縁からなる縁を四周にまわす。主室のトコや棚、付書院からなる座敷構えや室境の欄間など、秀逸な意匠でまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007182"},{"id":"00007180","register_sub_id":"101","register_pk":"108162","name":"富岡市社会教育館講堂棟","kana":"とみおかししゃかいきょういくかんこうどうとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.255508,"lng":138.860275,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積314㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0259","desc":"南面する入母屋造妻入で、正面に切妻造妻入玄関を付ける。屋根は桟瓦葺で、軒先を鉄板葺とする。内部は六十畳の講堂を中心に正・側面に広縁、背面に演壇等を設け、旧神殿を突出し、西面に渡廊下を付設。大きな入母屋破風と切妻屋根が威厳ある正面意匠をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007180"},{"id":"00007184","register_sub_id":"101","register_pk":"108166","name":"富岡市社会教育館正門","kana":"とみおかししゃかいきょういくかんせいもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.25496217,"lng":138.85970221,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺一部鉄板葺、間口3.6m、袖塀及び潜り付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0263","desc":"車寄の西南方に位置する一間薬医門で、袖塀と潜りを付設。間口３．６ｍと規模が大きい。屋根は切妻造で、軒先に鉄板をまわす桟瓦葺とする。主柱上に冠木と男梁を架し、男梁上に束で棟木を支持する。軒は一軒疎垂木。軸太で簡明な意匠にまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007184"},{"id":"00007183","register_sub_id":"101","register_pk":"108165","name":"富岡市社会教育館和室棟","kana":"とみおかししゃかいきょういくかんわしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県富岡市一ノ宮1465-1","lat":36.25513024,"lng":138.85934082,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積498㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"10 － 0262","desc":"玄関及び事務室棟の西南に位置する。北面に廊下を通し、三六畳の談話室と和室３室を１列に並べ、西側に食堂や厨房、便所などを付設。東西棟の寄棟造を主棟とし、東端には南北棟の入母屋造を直角に設け、西には寄棟造屋根を段違いに出し、見応えある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007183"},{"id":"00007003","register_sub_id":"101","register_pk":"107985","name":"日本基督教団島村教会島村めぐみ保育園本館","kana":"にほんきりすときょうだんしまむらきょうかいしまむらめぐみほいくえんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県伊勢崎市境島村2509-2","lat":36.244926,"lng":139.245636,"geo_status":"db","era":"昭和25／昭和28改修・昭和29増築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"10 － 0258","desc":"島村教会敷地から交差点を挟んで斜め向かいの敷地に建つ。北を正面とした東西棟で、屋根は切妻造瓦葺とし、北面の中央に緩勾配の寄棟屋根の玄関、東寄りの下屋を便所とする。外壁は下見板張で、妻壁上部を漆喰塗としており、本館に倣った意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007003"},{"id":"00015287","register_sub_id":"101","register_pk":"532411","name":"廣池千九郎大穴記念館偲ぶの湯（旧洞窟温泉）","kana":"ひろいけちくろう おおあなきねんかんしのぶのゆ（きゅうどうくつおんせん）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町大穴字髙平735-1","lat":36.79096111,"lng":138.98069167,"geo_status":"db","era":"昭和12年／平成15年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"コンクリート造、延長7.0m","structure_material":"コンクリート造","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0361","desc":"大穴温泉に位置する入浴施設。南面する崖面から湧き出す温泉の源を求め、岩盤を掘り広げ、素掘のヴォールト状トンネル奥に浴槽を配し、源泉の湧出口やトンネル入口の廻りをコンクリートで補強。廣池千九郎が晩年療養した温泉で、岩窟内にある独特な入浴施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015287"},{"id":"00015288","register_sub_id":"101","register_pk":"532412","name":"廣池千九郎大穴記念館脱衣場","kana":"ひろいけちくろう おおあなきねんかんだついば","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町大穴字髙平735-1","lat":36.790875,"lng":138.98071389,"geo_status":"db","era":"昭和12年／平成15年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0362","desc":"旧洞窟温泉の入口南にある脱衣場。高いコンクリート基礎に建つ平屋建切妻造で、屋根は杉皮葺の上に杉皮葺を重ね、外壁は杉皮張仕上。内部は二室で上部にキングポスト・トラスを現す。地元の杉材を多用した独特な外観で、廣池千九郎が臨終した記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015288"},{"id":"00015286","register_sub_id":"101","register_pk":"532410","name":"廣池千九郎谷川記念館神壇","kana":"ひろいけちくろう たにがわきねんかんしんだん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町谷川字上原557-1他","lat":36.79057222,"lng":138.95266944,"geo_status":"db","era":"昭和11年／昭和40年代改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0360","desc":"主屋の北に南面して建つ天照皇大神を祀る神殿。切妻造平入で屋根は割竹押縁の杉皮葺とし、外壁は杉皮張仕上。正面と側面の正面寄りに板戸を建て、内部は一室で幅一杯の上壇を構え祭壇とする。天井は割竹竿縁の杉皮張。地元杉材を多用した独特な外観の小社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015286"},{"id":"00015285","register_sub_id":"101","register_pk":"532409","name":"廣池千九郎谷川記念館麗澤館（旧主屋及び旧浴場）","kana":"ひろいけちくろう たにがわきねんかんれいたくかん（きゅうおもやおよびきゅうよくじょう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県利根郡みなかみ町谷川字上原557-1他","lat":36.79043889,"lng":138.95274167,"geo_status":"db","era":"昭和11年／昭和40年代改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0359","desc":"谷川温泉の木立の中に建つ旧療養施設。平屋建切妻造の主屋で東に浴場を接続。屋根は杉皮葺の上に杉皮葺の屋根を重ねる。内部は一二・五畳と七・五畳の続き間座敷とし、西面に床を構え、天井は割竹押縁の杉皮張とする。地元の杉材を多用した特異な外観の施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015285"},{"id":"00013508","register_sub_id":"101","register_pk":"504872","name":"旧壺春堂醫院主屋","kana":"きゅうこしゅんどういいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県秩父郡皆野町大字皆野字原1169-1他","lat":36.070775,"lng":139.09615278,"geo_status":"db","era":"江戸末期／明治前期増改築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積160㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"11 － 0198","desc":"金子兜太の父で俳人・医師の金子元春の住宅兼医院。南北棟の二階建切妻造で南妻が旧街道に面する。両妻に土台を入れ小屋を折置とした整形四間取の主屋に京呂組の客間を増築。客間座敷に兜太の書を飾る等、著名な俳人の生家として文学史上も価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013508"},{"id":"00013509","register_sub_id":"101","register_pk":"504873","name":"旧壺春堂醫院土蔵","kana":"きゅうこしゅんどういいんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父郡皆野町大字皆野字原1168-1","lat":36.07098889,"lng":139.09586111,"geo_status":"db","era":"昭和9年／昭和38年移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"11 － 0199","desc":"敷地北西寄りに西面して建つ。南北棟で二階建切妻造桟瓦葺。戸口は四段の掛子塗観音扉とし二階両妻にも三段掛子塗の窓を開ける。北妻に扇の鏝絵を飾る。内部は漆喰仕上で医療機器や家財等を収納した。主屋とともに地域の文化交流施設として景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013509"},{"id":"00005256","register_sub_id":"101","register_pk":"106244","name":"近藤歯科医院","kana":"こんどうしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町1026-6","lat":35.99523742,"lng":139.08300728,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積83㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0094","desc":"２階建の医院棟を核とし，平屋建の住居棟が接続し，全体はＬ字型の形態になる。通り側の外観はハーフティンバー風の真壁造で，壁をドイツ壁風に仕上げ，屋根は桟瓦葺とする。内部は医院棟を洋風とし，住居棟を和風とする。和洋の特徴を兼備した個人病院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005256"},{"id":"00004211","register_sub_id":"101","register_pk":"105201","name":"坂田医院旧診療所","kana":"さかたいいんきゅうしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県熊谷市妻沼1420","lat":36.222523,"lng":139.377441,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積217㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"11 － 0084","desc":"鉄筋コンクリート造，陸屋根造平屋建の産科医院診療棟。東面北寄りに車寄を突出させ，南北に調剤室・待合室・診察室・分娩室等を並べ，西側にレントゲン室等を配する。正側面はスクラッチタイル張とし，軒部にタイル張技法による歯飾状の装飾帯を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004211"},{"id":"00012876","register_sub_id":"101","register_pk":"367984","name":"栃谷八坂神社舞台","kana":"とちややさかじんじゃぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県秩父市栃谷字島府402-2","lat":36.02732222,"lng":139.11931944,"geo_status":"db","era":"明治32年／昭和25年頃・平成26年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"11 － 190","desc":"秩父盆地北部の神社にある地芝居舞台で、境内西側の広場に東面して建つ。寄棟造桟瓦葺の平屋建、正面は出桁造とし、差物を通して開放する。舞台は前二間を表、奧三間を裏とし、裏には可動式の二重舞台を備える。秩父地方の神社附設舞台の希少な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012876"},{"id":"00007004","register_sub_id":"101","register_pk":"107986","name":"日本基督教団島村教会島村めぐみ保育園別館","kana":"にほんきりすときょうだんしまむらきょうかいしまむらめぐみほいくえんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県深谷市横瀬字聖天68-1","lat":36.24478328,"lng":139.24592072,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"11 － 0119","desc":"島村教会敷地から交差点を挟んで斜め向かいの敷地に建つ。北を正面とした東西棟で、屋根は切妻造瓦葺とし、北面の中央に緩勾配の寄棟屋根の玄関、東寄りの下屋を便所とする。外壁は下見板張で、妻壁上部を漆喰塗としており、本館に倣った意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007004"},{"id":"00014453","register_sub_id":"101","register_pk":"512437","name":"本多流洗心洞（髙木道場）弓道場","kana":"ほんだりゅうせんしんどう（たかぎどうじょう）きゅうどうじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県久喜市下清久字鶴ノ谷395-11","lat":36.07516667,"lng":139.64840278,"geo_status":"db","era":"昭和7年頃／平成23年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"11 - 0219","desc":"旧清久村の旧家に所在する弓道場。切妻造で天井の高い板敷の射場を中心に、下屋で西に床構え付畳敷の上座、東に弓置場、北に畳敷の控えを配し、切妻造玄関を北東に設ける。控えの窓桟は矢羽根形とし、床天井の竿縁は弓なりに曲げる。木造の近代弓道場の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014453"},{"id":"00014454","register_sub_id":"101","register_pk":"512438","name":"本多流洗心洞（髙木道場）的場","kana":"ほんだりゅうせんしんどう（たかぎどうじょう）まとば","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県久喜市下清久字鶴ノ谷395-13","lat":36.07496667,"lng":139.64822778,"geo_status":"db","era":"昭和7年頃／平成23年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"11 - 0220","desc":"旧清久村の旧家に所在する弓道場の的場。切妻造で射場側を開放、残る三方を板壁とし、内部に安土を盛り上げる。コンクリート基礎と土台は安土断面を意識して背面側を高くする。左右に矢除板を配し、その背後に的置場を設ける。木造の近代弓道場的場の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014454"},{"id":"00001239","register_sub_id":"101","register_pk":"102229","name":"一木歯科医院","kana":"いちきしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県筑西市甲12","lat":36.31075701,"lng":139.97806752,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積30㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0012","desc":"大正１０年隣家の失火により類焼した後の再建建物のため防火に配慮した造りになる。木造鐵網コンクリート仕上げの数少ない遺存例として貴重。外観は、上げ下げ窓を割付けただけの単純な構成をとるが、プロポーションは的確で古典的な風格すら感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001239"},{"id":"00001165","register_sub_id":"101","register_pk":"102155","name":"旧共楽館（日立武道館）","kana":"きゅうきょうらくかん（ひたちぶどうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県日立市白銀町2-21-15","lat":36.611504,"lng":140.645523,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積1200㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"08 － 0006","desc":"日立鉱山が従業員や地域住民のために建設した大規模な妻入の劇場で、歌舞伎座（東京）を模したといわれる。正面入り口の左右に２階建、唐破風屋根の階段室が附属する。内部は、屋内体育館として改造されているが、堂々たる外観は地域の象徴ともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001165"},{"id":"00010909","register_sub_id":"101","register_pk":"208880","name":"旧樋口病院入院棟","kana":"きゅうひぐちびょういんにゅういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字大子字泉町北側705","lat":36.771032,"lng":140.353939,"geo_status":"db","era":"昭和30／平成26改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"08-0282","desc":"大子駅から東に延びる通りに南面して建つ。奥行の長い木造二階建で、正面玄関脇には旧車庫を設ける。中廊下の両側に、一階には診察室等を、二階には病室を並べる。正面妻側には柱形を見せて垂直性を強調。縦桟で細長く割り付けるガラス窓も当時の特徴を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010909"},{"id":"00004512","register_sub_id":"101","register_pk":"105502","name":"武石家住宅主屋","kana":"たけいしけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町1107-1","lat":36.31234,"lng":140.567322,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積133㎡","structure_material":"木造平屋一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0172","desc":"洋館を医院，和館を住宅として建設。洋館は木造２階建，寄棟造，桟瓦葺で，外壁をドイツ下見板張とし，胴蛇腹を廻す。玄関庇は瓔珞形の鼻隠で飾る。１階が診察室，２階は書斎と子供室であった。和館は寄棟造の平屋建。地方における大正期医院併用住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004512"},{"id":"00014733","register_sub_id":"101","register_pk":"518991","name":"土浦市民会館","kana":"つちうらしみんかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和後","pref":"茨城県","address":"茨城県土浦市東真鍋町1480-2","lat":36.09126389,"lng":140.20506111,"geo_status":"db","era":"昭和44年／令和2年改修","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造3階建、陸屋根、建築面積2，674㎡","structure_material":"鉄筋コンクリート造一部鉄骨造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"08 - 0319","desc":"建物の南正面全幅を階段とし、角柱の列柱廊をガラス壁で画し、吹抜のホワイエとする。東側の三階分を占める大ホールは側面壁と天井の曲面で音響を整える。西側二、三階を占める小ホールは傾斜席の靴箱形。佐藤武夫の設計による古典主義的意匠の外観が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014733"},{"id":"00004514","register_sub_id":"101","register_pk":"105504","name":"幕末と明治の博物館別館","kana":"ばくまつとめいじのはくぶつかんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町字見付久保8231-4","lat":36.32144237,"lng":140.58308887,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積591㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0174","desc":"聖像殿と渡廊下で接続する鉄筋コンクリート造平屋建。展示室外壁は無窓で，石造風に目地を切った擬石仕上とし，角形付柱が区画する重厚な外観意匠である。軒下には歯飾を施す。第１展示室の南面には窓を設け，コリント風円柱を並べてアクセントとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004514"},{"id":"00007342","register_sub_id":"101","register_pk":"108324","name":"石原家住宅主屋","kana":"いしはらけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県印旛郡栄町北辺田字前原573-1","lat":35.853152,"lng":140.26213534,"geo_status":"db","era":"明治7／昭和55頃改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積199㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"12 － 0115","desc":"敷地の中央に東面して建つ。桁行８間半梁間６間の木造平屋建で、寄棟造茅葺（鉄板仮葺）とし、正面北端に入母屋造の玄関を構える。内部は北寄りに奥座敷などを一列に並べ、南側の東半部を医療施設、西半部を住居にあてる。医院併用住宅として特徴的な構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007342"},{"id":"00001243","register_sub_id":"101","register_pk":"102233","name":"和泉公会堂","kana":"いずみこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県鴨川市和泉1612","lat":35.128761,"lng":140.102707,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積314㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0024","desc":"明治４２年着工された耕地整理の完成を機に建設された地区住民の共有建築物。耕地整理の記念碑的建造物でもある。瓦葺寄棟屋根の主屋の外周に庇を差出し、正面中央にムクリ入母屋の車寄玄関を突出させた、和風公会堂建築に共通した形態をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001243"},{"id":"00000236","register_sub_id":"101","register_pk":"101226","name":"興風会館","kana":"こうふうかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田250","lat":35.94276827,"lng":139.8635723,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建，建築面積527㎡","structure_material":"鉄筋コンクリート造4階建","registered":"1997.07.15(平成9.07.15)","register_no":"12 － 0005","desc":"正面のファサードはルネッサンス風の意匠を基調とし、ロマネスク風アーチからなるゆったりとした玄関部はじめ全体として威圧的にならない構成にまとめ上げる。設計大森茂、施工戸田組。２階講堂の空間構成や、階段廻りの意匠など建築的に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000236"},{"id":"00000237","register_sub_id":"101","register_pk":"101227","name":"武田家住宅","kana":"たけだけじゅうたく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県市原市古市場53","lat":35.54169917,"lng":140.15029449,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建，瓦葺，建築面積185㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"12 － 0006","desc":"元は和風の建物であったが、昭和３年建設の左半分の建屋に、昭和３１年に右半分の建屋を移築し結合した。その際、外壁のみ左手の建屋に合わせて洋風に改修されて和風屋根との折衷形式となった。特異な外観の住宅（元医院）として、地域の象徴となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000237"},{"id":"00015412","register_sub_id":"101","register_pk":"533427","name":"千葉県立美術館展示棟","kana":"ちばけんりつびじゅつかんてんじとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"千葉県","address":"千葉県千葉市中央区中央港一丁目104","lat":35.60115,"lng":140.10100833,"geo_status":"db","era":"昭和49年／平成24年改修","year":1974,"year_source":"db","year_min":1974,"year_max":1974,"year_label":null,"structure":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建、鉄板葺、建築面積5，032㎡","structure_material":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"12 - 0336","desc":"千葉港中央地区の臨海公園に位置する美術館。設計は大髙建築設計事務所。鉄筋コンクリート造及び鉄骨造の展示室をグリッド状に配して拡張可能とし、それぞれ傾斜屋根と外壁炻器質タイルを用いて、外観にまとまりをみせる。大髙正人による初期の美術館の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015412"},{"id":"00013692","register_sub_id":"101","register_pk":"505209","name":"野田市郷土博物館","kana":"のだしきょうどはくぶつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県野田市野田字谷端370-8","lat":35.94534722,"lng":139.86547778,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積257㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"12 － 307","desc":"山田守設計の博物館。鉄筋コンクリート造二階建で正面中央に玄関を付す。リシン仕上に横目地を入れ、プレキャストコンクリートの竪格子をはめた横長の開口部等、水平を意識したモダニズムに連なる外観意匠。内部は自然光を間接的に取込むなど環境設計も秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013692"},{"id":"00013054","register_sub_id":"101","register_pk":"504383","name":"稲荷湯長屋","kana":"いなりゆながや","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都北区滝野川六丁目27-5","lat":35.74473333,"lng":139.72453333,"geo_status":"db","era":"昭和2年／昭和5年頃移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0427","desc":"浴場兼主屋の東側に東面して建つ。木造平屋建、金属板葺で、一棟二戸の長屋である。従業員の住居であったと考えられる。内部は各戸とも下手に玄関と奥に三畳、上手に押入付の六畳とし、便所を附属する。銭湯の職住一体経営の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013054"},{"id":"00013053","register_sub_id":"101","register_pk":"504382","name":"稲荷湯浴場兼主屋","kana":"いなりゆよくじょうけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都北区滝野川六丁目27-5","lat":35.744675,"lng":139.72442222,"geo_status":"db","era":"昭和5年／昭和33年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積361㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"13 － 0426","desc":"板橋駅東方の住宅地で通りに北面する銭湯。北半を浴場、南半を主屋とし、浴場正面に入母屋造の玄関部を構える。東半を男湯、西半を女湯とし、玄関奥に脱衣場、流し場、浴槽を配す。破風が三段に連なる正面意匠など、戦前の東京における銭湯の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013053"},{"id":"00000630","register_sub_id":"101","register_pk":"101620","name":"大倉集古館陳列館","kana":"おおくらしゅうこかんちんれつかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都港区虎ノ門2-10-3","lat":35.667079,"lng":139.74339573,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造２階建，銅板葺，建築面積863㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0011","desc":"大倉喜八郎本邸に設けられた私設美術館の震災復興建築。伊東忠太の設計によるもので，伊東忠太の東洋建築に関する蘊蓄を披瀝した作品として知られる。陳列館東面から敷地低地に連なっていたかっての入口部分は失われて現存しない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000630"},{"id":"00001565","register_sub_id":"101","register_pk":"102555","name":"温故学会会館","kana":"おんこがっかいかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区東2-9-1","lat":35.654331,"lng":139.711395,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積187㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0080","desc":"「群書類従」などの版木約２万枚を収蔵する目的で建設されたＲＣ造二階建。左翼一階を事務所，二階を和風の講堂，右翼各階を収蔵庫とする。正背面にバットレスが立ち並ぶ簡明な意匠を特色とし，正面中央に円形の玄関ポーチを張り出す。設計・施工は清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001565"},{"id":"00003070","register_sub_id":"101","register_pk":"104060","name":"学士会館","kana":"がくしかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区神田錦町3-28","lat":35.693192,"lng":139.758987,"geo_status":"db","era":"昭和3／昭和12増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上5階地下1階建、建築面積1839㎡","structure_material":"鉄骨鉄筋コンクリート造地上5階地下1階建","registered":"2003.01.31(平成15.01.31)","register_no":"13 － 0134","desc":"ホール，サロン，宿泊施設などの機能を持つ。ＳＲＣ造による関東大震災後の復興建築で，玄関の半円大アーチやスクラッチタイルの外観，窓廻り２・３層の直線基調と４層の曲線基調の対比などに特徴がある。設計は佐野利器と高橋貞太郎（増築部は藤村朗）。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003070"},{"id":"00014753","register_sub_id":"101","register_pk":"519011","name":"旧柏湯","kana":"きゅうかしわゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区谷中六丁目17","lat":35.72176111,"lng":139.77050278,"geo_status":"db","era":"昭和26年／平成5年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階建、瓦葺及び鉄板葺、建築面積177㎡","structure_material":"木造一部鉄筋コンクリート造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0498","desc":"谷中の尾根道の南東角地に建つかつての銭湯。北道路側に突出した玄関は引分け戸の上部に筬欄間を入れる。入母屋造の大屋根下が旧脱衣室で、南の旧浴場は上部中央を立上げて高窓とする。南端の二階建部分は旧火焚場。昭和初期から流行した宮造り銭湯の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014753"},{"id":"00012303","register_sub_id":"101","register_pk":"531627","name":"旧砂堀医院","kana":"きゅうすなぼりいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都目黒区目黒三丁目533-59","lat":35.63189167,"lng":139.70479167,"geo_status":"db","era":"昭和12年頃／昭和40年代・同60年代・平成24年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、金属板葺、建築面積66㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-409","desc":"住宅地の路地に西面して建つ。切妻造平入の北側に切妻造妻入の別棟を接続し、下屋を廻して一つにまとめる。内部はホールを中心に待合や診察室、応接室等を配する。改変多いが、大壁モルタル仕上や腰スクラッチタイル張、縦長窓が昭和の洋風住宅の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012303"},{"id":"00001501","register_sub_id":"101","register_pk":"102491","name":"旧清明文庫","kana":"きゅうせいめいぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区南千束2-3-1","lat":35.60212051,"lng":139.692261,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積548㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0072","desc":"東洋文明の啓蒙活動を行っていた清明会が設立した清明文庫の本館で，戦後出版社の所有となり鳳凰閣と称す。内装はモザイクタイルを用いるなど要所を飾るが，外壁は装飾的要素を控えた簡明なデザインとし，正面玄関上から立ち上がる４本の柱型に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001501"},{"id":"00007193","register_sub_id":"101","register_pk":"108175","name":"旧東京市深川食堂","kana":"きゅうとうきょうしふかがわしょくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区門前仲町1-19-15","lat":35.67407431,"lng":139.794922,"geo_status":"db","era":"昭和7／昭和20頃改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"13 － 0234","desc":"角地に建つＲＣ造２階建。南面西端をエントランスとし、その奥を、２階天井まで全面窓で明るく開放的な階段室とする。当初は２階南面には水平に連続するスチール・サッシュ窓が設けられた。震災復興事業で建設された食堂で、当時の建築デザインの潮流を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007193"},{"id":"00013234","register_sub_id":"101","register_pk":"366223","name":"旧三井文庫第二書庫","kana":"きゅうみついぶんこだいにしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都品川区豊町一丁目1131-1","lat":35.61228333,"lng":139.72053611,"geo_status":"db","era":"大正11年／大正15年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造3階建、金属板葺、建築面積130㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2020.04.03(令和2.04.03)","register_no":"13 － 0430","desc":"区立公園文庫の森に建つ、三井家史料管理のための書庫。鉄筋コンクリート造、二重の壁式構造で、一階を含む各階床と三階天井は鉄筋コンクリート造スラブとし、防火に優れた堅牢な造り。書架の鉄骨支柱で床を支持するなどの工夫がみられ、技術的価値が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013234"},{"id":"00004948","register_sub_id":"101","register_pk":"105938","name":"黒沢ビル","kana":"くろさわびる","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都台東区上野2-40","lat":35.70906486,"lng":139.77054045,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積144㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"13 － 0188","desc":"小川眼科病院として建設。鉄筋コンクリート造，地上３階地下１階建で，正面１階の鉄平石張，尖頭アーチ窓やコンクリート製幌状の庇など表現派風意匠に特徴がある。屋上には温室風の紫外線療法室が残り，室内随所に小川三知作ステンドグラスをみることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004948"},{"id":"00005585","register_sub_id":"101","register_pk":"106573","name":"国際文化会館本館","kana":"こくさいぶんかかいかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区六本木5-11-16","lat":35.65852616,"lng":139.733368,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積2824㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0199","desc":"敷地中央に北面して建ち，南側に広大な日本庭園をもつ。ＲＣ造３階建，地下１階で，２階以上を宿泊施設とし，１階及び地階を会議室，ホール等とする。木製建具を使った宿泊部分の軽快なモダニズムの外観意匠と日本庭園が融合する日本近代建築の傑作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005585"},{"id":"00009921","register_sub_id":"101","register_pk":"196068","name":"国立天文台表門","kana":"こくりつてんもんだいおもてもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67514943,"lng":139.53887173,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造、間口5.5m、左右通用門付","structure_material":"コンクリート造","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0336","desc":"敷地東面に開く。中央門と左右脇門の四本の門柱からなる。門柱は鉄管を芯としたコンクリート造の表面に角石を乱れ張りとし、隅部は几帳面を取り、柱頭と足下の石にはフルーティングを施す。中央門柱の上には照明器具を据える。国立天文台の玄関口を飾る門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009921"},{"id":"00009919","register_sub_id":"101","register_pk":"196066","name":"国立天文台旧図庫及び倉庫","kana":"こくりつてんもんだいきゅうずこおよびそうこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67486706,"lng":139.53694001,"geo_status":"db","era":"昭和5／昭和36改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、金属板葺、建築面積100㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0334","desc":"敷地中ほどに位置する。鉄筋コンクリート二階建で、窓の上下には水平に連続する小庇を付す。一階には丸窓を付ける。西にモルタル塗の増築部が付くが、当初から増築の想定がなされていた。シンプルな外観やスクラッチタイル貼仕上げに昭和初期の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009919"},{"id":"00009916","register_sub_id":"101","register_pk":"196063","name":"国立天文台ゴーチェ子午環室","kana":"こくりつてんもんだいごーちぇしごかんしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67494286,"lng":139.53590987,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積129㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0331","desc":"子午線上の天体の精密位置観測のための子午環を納める半円形立面を持つ建物。軸線を正確に南北に据え、建物から独立した中央の基礎に子午環を置く。建物の基礎及び側壁は鉄筋コンクリート造で、東西に出入口を付し、屋根は鉄骨造で観測時には屋根中央が開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009916"},{"id":"00009917","register_sub_id":"101","register_pk":"196064","name":"国立天文台第一子午線標室","kana":"こくりつてんもんだいだいいちしごせんひょうしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67424258,"lng":139.53529576,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積7.3㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0332","desc":"子午環室の南一〇〇メートルに位置し、子午環の規準点となる子午線標を納める。鉄筋コンクリート造二階建で北面を三角形の土留擁壁とし、背面は土盛とする。二階に子午線標を納め、擁壁前面に取付く階段で出入りする。子午環の南北軸の精度確保を担う施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009917"},{"id":"00002621","register_sub_id":"101","register_pk":"103611","name":"国立天文台第一赤道儀室","kana":"こくりつてんもんだいだいいちせきどうぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-21-1","lat":35.674274,"lng":139.538559,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積50㎡、ドーム付","structure_material":"鉄筋コンクリート造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0126","desc":"構内の直線道路を介して大赤道儀室と対面する。外観左右対称の張出通路付ＲＣ造円筒状躯体の上に，手動で屋根の開閉と回転を行う直径５．６ｍの鉄骨造ドームが載り，口径２０ｃｍのツァイス製望遠鏡を収める。大赤道儀室と同様，東京帝国大学営繕課の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002621"},{"id":"00002620","register_sub_id":"101","register_pk":"103610","name":"国立天文台大赤道儀室","kana":"こくりつてんもんだいだいせきどうぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-21-1","lat":35.674274,"lng":139.536743,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積238㎡、ドーム付","structure_material":"鉄筋コンクリート造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0125","desc":"市西部の雑木林を残す敷地内にある。頂部にロンバルト帯風の蛇腹を廻した円筒状ＲＣ造躯体に，直径１５ｍの銅板葺鉄骨造ドームを載せ総高19.5ｍとする。ツァイス製望遠鏡の鏡筒の方向・傾きに合わせて，ドーム回転と円形観測床の回転及び傾斜角調節を行う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002620"},{"id":"00009918","register_sub_id":"101","register_pk":"196065","name":"国立天文台第二子午線標室","kana":"こくりつてんもんだいだいにしごせんひょうしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.67577611,"lng":139.53575114,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積7.2㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0333","desc":"子午環室の北一〇〇メートルに位置する。第一子午線標室と同型の建物で、子午環室を挟んで南北対称に配置される。内部の子午線標は鉄筋コンクリート基礎の上に置かれるが、建物とは縁が切られている。天文台ならではの自然環境から精密測定機器を守る建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009918"},{"id":"00000565","register_sub_id":"101","register_pk":"101555","name":"国立天文台太陽分光写真儀室","kana":"こくりつてんもんだいたいようぶんこうしゃしんぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢2-21-1","lat":35.67334615,"lng":139.53671256,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積331㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"13 － 0010","desc":"アインシュタインの相対性原理の検証を主目的として建てられ，アインシュタイン塔の名で知られる。観測室を頂部にもつ塔状の外観が特徴で，塔の内部には建物と絶縁された機械室が上部までつながっており，その周囲に階段と準備室が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000565"},{"id":"00009920","register_sub_id":"101","register_pk":"196067","name":"国立天文台門衛所","kana":"こくりつてんもんだいもんえいじょ","category":"文化福祉","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.6752601,"lng":139.53877926,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0335","desc":"正門北に建つ。木造平屋建切妻造平入で、正面に切妻屋根の玄関を付し、玄関上部や妻面にハーフティンバー風の意匠を見せ、外壁を下見板張とするなど洋風意匠とする。内部は中央を壁で仕切り、それぞれ六畳と四畳半の和室と便所を持つ左右対称の平面であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009920"},{"id":"00009915","register_sub_id":"101","register_pk":"196062","name":"国立天文台レプソルド子午儀室","kana":"こくりつてんもんだいれぷそるどしごぎしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都三鷹市大沢2-1007-1","lat":35.6749584,"lng":139.53640523,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積36㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0330","desc":"子午線上を通過する天体を観測し、その地の経度や時刻を決める子午儀を納める建物。ゼツェッション風の意匠を持つ鉄筋コンクリート造平屋建の建物で、鉄骨造の小屋組はレール上に据えられ、観測時には鉄骨造の切妻屋根が中央から開き、子午儀上方を開放する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009915"},{"id":"00013358","register_sub_id":"101","register_pk":"504384","name":"小杉湯","kana":"こすぎゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区高円寺北三丁目1003-11","lat":35.70808333,"lng":139.64882222,"geo_status":"db","era":"昭和8年／昭和38年・同46年増築、平成29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺及び金属板葺、建築面積287㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0436","desc":"高円寺駅北の商店街に所在する公衆浴場。脱衣室屋根の東正面に千鳥破風を掲げ、一階の唐破風庇下が旧入口である。浴室は中央に越屋根を掲げて高窓とし、西壁には男女の浴室にわたるペンキ絵を描く。改修はあるが、東京でよく見られた銭湯の典型例の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013358"},{"id":"00011889","register_sub_id":"101","register_pk":"354915","name":"五島美術館本館","kana":"ごとうびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都世田谷区上野毛三丁目112-3他","lat":35.612275,"lng":139.635627,"geo_status":"db","era":"昭和35年／平成24年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階一部地下1階建、建築面積1143㎡","structure_material":"鉄筋コンクリート造平屋一部2階一部地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"13-386","desc":"東急電鉄の創業者五島慶太の喜寿を記念したもの。設計は吉田五十八で、鉄筋コンクリート造による伝統表現を意図し、寝殿造を参照した平面や大径の丸柱、蔀戸や御簾の建具意匠、幅広の縁や深い軒による水平線の強調など平安朝の意匠を模す吉田五十八の代表作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011889"},{"id":"00015418","register_sub_id":"101","register_pk":"533433","name":"駒澤大学旧図書館（禅文化歴史博物館・耕雲館）","kana":"こまざわだいがくきゅうとしょかん（ぜんぶんかれきしはくぶつかん・こううんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区駒沢一丁目3403-1","lat":35.62850556,"lng":139.65812222,"geo_status":"db","era":"昭和3年／平成13年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造一部鉄骨造地上2階地下1階建、建築面積544㎡","structure_material":"鉄骨鉄筋コンクリート造一部鉄骨造地上2階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0527","desc":"駒沢オリンピック公園北側の大学内に建つ旧図書館。設計は菅原榮蔵。八角形ドームを頂く吹抜の旧大閲覧室を中心に事務室等を配する。ステンドグラスなどの幾何学的意匠はライト風で、スクラッチタイル貼の屏風状に広がる外観など自在なデザインが異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015418"},{"id":"00016497","register_sub_id":"101","register_pk":"574859","name":"十四世喜多六平太記念能楽堂","kana":"じゅうよんせいきたろっぺいたきねんのうがくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"東京都","address":"東京都品川区上大崎四丁目245-1他","lat":35.63362889,"lng":139.71477778,"geo_status":"db","era":"昭和48年／令和7年改修","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上2階地下2階建、建築面積626㎡、舞台及び橋掛付","structure_material":"鉄骨鉄筋コンクリート造地上2階地下2階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0528","desc":"目黒駅付近に位置し、喜多流十四世宗家を記念した常設能楽堂。設計は榛沢敏郎。鉄骨鉄筋コンクリート造地上2階地下2階建で能舞台を内包する。主体部外観は地上より持上げて軽快にみせ、御影石張の階段やトラバーチン貼の壁面が入口アプローチを巧みに構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016497"},{"id":"00016654","register_sub_id":"101","register_pk":"579138","name":"松連庵(旧松連寺庫裏)","kana":"しょうれんあん（きゅうしょうれんじくり）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都日野市百草560","lat":35.654228,"lng":139.427061,"geo_status":"db","era":"江戸後期／昭和中期・令和7年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積178㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"13 - 0533","desc":"多摩川丘陵南東端に広がる百草園内に東面して建つ旧松連寺の庫裏。桁行八間半、梁間四間、寄棟造平入茅葺で、正面に二間半の式台を構え差掛け屋根を付す。内部は北を土間とする六間取で、端正な床構え付き座敷を設ける。旧庫裏を転用した茅葺屋根の園内施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016654"},{"id":"00015298","register_sub_id":"101","register_pk":"532422","name":"ソルフェージスクール","kana":"そるふぇーじすくーる","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"東京都","address":"東京都豊島区目白四丁目1434-2","lat":35.72548333,"lng":139.70059722,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"鉄筋コンクリート造3階建、人工スレート葺、建築面積96㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0519","desc":"目白駅北西方の住宅街に建つ、吉村順三がバイオリニストの妻のために設計した音楽教室。一・二階の教室や階段は丁寧な造作で三階ホールは斜線規制に則した勾配屋根で天井高を確保し水平窓で巧みに分節する。吉村による一連の音楽施設の初期作品として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015298"},{"id":"00001498","register_sub_id":"101","register_pk":"102488","name":"高橋診療所","kana":"たかはししんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区山王3-30-5","lat":35.586273,"lng":139.726044,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0069","desc":"ＪＲ大森駅西側の池上通り商店街に，住宅を兼ねた診療所として建設。診療室を除き内部は改造されているが，昭和初期に流行したスパニッシュ風の外観を残す。近在の宅地化に伴って洒落た商店建築等が建ち並んでいた町並の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001498"},{"id":"00002618","register_sub_id":"101","register_pk":"103608","name":"東京文化財研究所黒田記念館書庫","kana":"とうきょうぶんかざいけんきゅうじょくろだきねんかんしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区上野公園12-53","lat":35.719067,"lng":139.773453,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積70㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0123","desc":"本館の北東に隣接して建てられた鉄筋コンクリート造３階建の矩形平面を有す建築物。美術研究所の書庫として建設。各壁面に縦長の開口部を設けていた。本館と同様のスクラッチタイル張の外装仕上げとし，本館と連続的な街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002618"},{"id":"00002617","register_sub_id":"101","register_pk":"103607","name":"東京文化財研究所黒田記念館本館","kana":"とうきょうぶんかざいけんきゅうじょくろだきねんかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区上野公園12-53","lat":35.71893524,"lng":139.7733612,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建半地下階付、建築面積463㎡、煙突付","structure_material":"鉄筋コンクリート造2階建半地下階付","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0122","desc":"東京芸術大学音楽学部敷地と同ブロックの角地に建つ。黒田清輝の遺言により建設された美術館施設で，２階に展示室を設ける。外観はスクラッチタイル張りで，正背面２階中央にイオニア式列柱６本を配してほぼ左右対称の端整な立面をつくる。設計は岡田信一郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002617"},{"id":"00001248","register_sub_id":"101","register_pk":"102238","name":"日本工業倶楽部会館","kana":"にほんこうぎょうくらぶかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都千代田区丸の内1-4-6","lat":35.68334265,"lng":139.76480432,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄骨造、鉄筋コンクリート造及び鉄筋鉄筋コンクリート造地上5階地下4階建、6階以上部分を除く、建築面積1877㎡","structure_material":"鉄骨造","registered":"1999.08.23(平成11.08.23)","register_no":"13 － 0055","desc":"東京駅駅頭に建つアメリカ式オフィスビルの形態にユーゲント・シュティルの意匠を加味した大正建築。我が国工業界のシンボル的建築で、正面中央パラペット上部の人像彫刻は当時の二大工業（石炭と紡績）を表す。設計は横河工務所、松井貴太郎の担当とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001248"},{"id":"00016500","register_sub_id":"101","register_pk":"574862","name":"日野市立中央図書館","kana":"ひのしりつちゅうおうとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和後","pref":"東京都","address":"東京都日野市豊田二丁目49-2","lat":35.65623694,"lng":139.38236694,"geo_status":"db","era":"昭和48年／令和元年改修","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積904㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0531","desc":"豊田駅南方に位置する市立中央図書館。鉄筋コンクリート造地上2階地下１階建、外壁は焼過煉瓦積。選書の快適さを重視し、開架室は吹抜の庭側を全面ガラス窓とするなど、初代館長前川恒雄の構想を建築家鬼頭梓が具現化。現代公共図書館の起点となった建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016500"},{"id":"00004528","register_sub_id":"101","register_pk":"105518","name":"山本歯科医院","kana":"やまもとしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区神田須田町1-3-3","lat":35.69608772,"lng":139.76918079,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造3階建、亜鉛メッキ鋼板葺、建築面積48㎡","structure_material":"木造3階建","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0182","desc":"靖国裏通り沿いに北面して建つ，木造３階建，切妻造，金属板葺の診療所兼住宅。入口付近等に改造が認められるが，全体に創建時の様子を良く残す。関東大震災復興期における看板建築の遺構で，軒蛇腹，看板，菱形装飾などによる正面の外観意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004528"},{"id":"00008656","register_sub_id":"101","register_pk":"149377","name":"矢来能楽堂","kana":"やらいのうがくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都新宿区矢来町60-1","lat":35.70289459,"lng":139.73244709,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"converted","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋一部地下1階建、瓦葺、建築面積432㎡、舞台及び橋掛付","structure_material":"木造平屋一部地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0279","desc":"市街地に所在する能楽堂。木造平屋1部地下1階建、建築面積432㎡。棟の高い切妻造桟瓦葺を中心に、玄関やロビー他を周囲に付設する。外壁モルタル仕上げ。舞台や橋掛のほか、楽屋や地下通路、客席を設け、風格のある内部空間を創出する。近代能楽堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008656"},{"id":"00007732","register_sub_id":"101","register_pk":"108714","name":"代々木能舞台敷舞台及び座敷","kana":"よよぎのうぶたいしきぶたいおよびざしき","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区代々木4-36-42","lat":35.6808947,"lng":139.68964368,"geo_status":"db","era":"昭和8／昭和25改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"13-0247","desc":"桁行１４ｍ梁間６．４ｍ、東西棟の木造平屋建。トコや棚を構える十七畳半の座敷を東に、敷舞台を西に設ける。敷舞台は小規模ながら後座と地謡座を備え、格天井を張り、木鼻付虹梁を掛け、蟇股を置く。座敷は舞台の桟敷でもあり、舞台側の北面窓を大きく開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007732"},{"id":"00007731","register_sub_id":"101","register_pk":"108713","name":"代々木能舞台舞台・橋掛・鏡の間","kana":"よよぎのうぶたいぶたい・はしがかり・かがみのま","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都渋谷区代々木4-36-42","lat":35.68098353,"lng":139.68964164,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋一部地下1階建、銅板葺、建築面積84㎡","structure_material":"木造平屋一部地下1階建","registered":"2009.08.07(平成21.08.07)","register_no":"13-0246","desc":"舞台は桁行５．５ｍ梁間５．４ｍの切妻造妻入で、背面に後座、側面に地謡座を付ける。面取方柱で大斗肘木組、化粧屋根裏天井。橋掛は舞台に直角に付き、桁行９．５ｍ梁間１．９ｍの化粧屋根裏天井で、西端が鏡の間へ通じる。丁寧に造られた本格的な能舞台。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007731"},{"id":"00014758","register_sub_id":"101","register_pk":"519016","name":"龍子記念館","kana":"りゅうしきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都大田区中央四丁目1034-2-1","lat":35.58237222,"lng":139.71555833,"geo_status":"db","era":"昭和37年／平成3年・同23年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、陸屋根一部瓦葺、建築面積747㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0503","desc":"川端龍子の作品を展示する記念館。角地に建つ鉄筋コンクリート造2階一部3階建で、全体をクの字とした特異な平面で１階をピロティ、2階を展示室とする。西隅3階部分は青い釉薬瓦葺の宝形造屋根で、竜舌蘭の宝珠を載せた姿は、地域のランドマーク的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014758"},{"id":"00016656","register_sub_id":"101","register_pk":"579140","name":"伊東医院住居棟","kana":"いとういいんじゅうきょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市戸塚区矢部町字矢部町14-1他","lat":35.402956,"lng":139.536817,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、天然スレート葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0368","desc":"診療所の南側に西面して建つ住居棟。切妻破風を正面に見せた急勾配のスレート葺洋館の背面に、中廊下沿いに座敷を並べる和館を配す。座敷欄間の組子は技巧的で、書院の下地窓など数寄屋風意匠を取込む。破風に持送を付し、外観華やかな洋館付き近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016656"},{"id":"00016655","register_sub_id":"101","register_pk":"579139","name":"伊東医院診療棟","kana":"いとういいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市戸塚区矢部町字矢部町14-1他","lat":35.403008,"lng":139.536688,"geo_status":"db","era":"大正14年／平成7年・令和2年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積95㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0367","desc":"旧東海道戸塚宿沿いの敷地に北面して建つ診療所。木造２階建半切妻造、外壁モルタル洗出仕上で上下窓を開ける。玄関ポーチの庇は幾何学意匠の持送で支え、正面軒に半円形の破風を飾る。地域医療を支えてきた診療所で、内部の室構成も良く残る上質な近代建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016655"},{"id":"00016657","register_sub_id":"101","register_pk":"579141","name":"伊東医院門及び塀","kana":"いとういいんもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市戸塚区矢部町字矢部町14-1他","lat":35.403078,"lng":139.536624,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 鉄筋コンクリート造、間口2.4m 塀 鉄筋コンクリート造、総延長19m","structure_material":"門 鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0369","desc":"旧東海道沿いに配された門及び塀。門柱は主体部を切石貼とする他はモルタル洗出で仕上げる。塀は出隅にアールを付け、腰は色を変えて横目地を切り、上部に木製ガラリを嵌込んだ開口を連続的に穿つ。全体に丁寧なつくりで診療所とともに歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016657"},{"id":"00001662","register_sub_id":"101","register_pk":"102652","name":"鎌倉国宝館本館","kana":"かまくらこくほうかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下2-1051-2","lat":35.32472551,"lng":139.55691185,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積799㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"14 － 0040","desc":"鉄筋コンクリート造による高床式校倉風建築。設計は岡田信一郎。寄棟状屋根の中央部には小屋裏位置に採光用の越屋根を隠し、内部では虹梁大瓶束形式で採光用越屋根の棟を支える造りとするなど和風表現と近代的技法との調和に苦心した跡がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001662"},{"id":"00015007","register_sub_id":"101","register_pk":"529285","name":"旧鎌倉図書館","kana":"きゅうかまくらとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市御成町18-35","lat":35.31871944,"lng":139.54813056,"geo_status":"db","era":"昭和11年／令和5年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積163㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0352","desc":"市役所東側の敷地に南面して建つ。木造二階建の外観は一・二階通しの柱形を付し縦長窓を多用。腰は緑青釉薬スクラッチタイル貼、懸魚を付した大きな切妻屋根を架ける。階段柱にはアールデコ調意匠をあしらう。シンプルな和洋折衷意匠が特徴的な図書館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015007"},{"id":"00008268","register_sub_id":"101","register_pk":"133910","name":"旧後藤医院鵠沼分院","kana":"きゅうごとういいんくげぬまぶんいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市鵠沼橘1-1850-40","lat":35.3342685,"lng":139.48408678,"geo_status":"db","era":"昭和8年／平成4年・平成19年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"14 － 0165","desc":"東に街路に面する矩形敷地に建つ。桁行２０ｍ梁間８．４ｍの木造平屋建、東西棟の入母屋造銅板葺。東半部を医院、西半部を住居とした。通風のため床高を高く、出窓を付け二重窓とし、換気用の越屋根を三ヶ所設置するなど機能向上のための工夫がなされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008268"},{"id":"00012308","register_sub_id":"101","register_pk":"531632","name":"旧長濱検疫所一号停留所","kana":"きゅうながはまけんえきしょ１ごうていりゅうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市金沢区海の公園10","lat":35.35961389,"lng":139.63503056,"geo_status":"db","era":"明治中期／大正後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、金属板葺、建築面積420㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"14 - 0257","desc":"検疫対象者の旧宿泊施設。切妻造鉄板葺で、コの字形平面の主体部に停留室八室を設け、両端突出部に食堂と談話室を配する。外壁は下見板張、上下窓を基調としながら突出部の先端にベイウィンドウを用いて変化を付ける。横浜最古級の洋風建築として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012308"},{"id":"00012137","register_sub_id":"101","register_pk":"352936","name":"旧南湖院第一病舎","kana":"きゅうなんこいんだいいちびょうしゃ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県茅ヶ崎市南湖七丁目12869-201","lat":35.319634,"lng":139.388952,"geo_status":"db","era":"明治32年／昭和54年・同58年・平成15年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、スレート葺、建築面積115㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"14-256","desc":"敷地北寄りに建つ木造二階建。矩形平面で北面に切妻屋根の玄関部、西面に階段室を張出して立面に変化を付ける。外壁は下見板張で上下窓を並べ、二階窓にペディメントを飾り、開口が多く採光通風に配慮する。療養地として著名な湘南で希少な明治期の結核病棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012137"},{"id":"00014582","register_sub_id":"101","register_pk":"515124","name":"旧広田医院主屋","kana":"きゅうひろたいいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県高座郡寒川町一之宮一丁目1126-1","lat":35.36378889,"lng":139.38482222,"geo_status":"db","era":"大正15年／昭和4年増築、昭和21年改修、昭和30年代増築","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積225㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0331","desc":"大山街道沿いの旧家の洋館付和風住宅。平屋建和館部は田の字型間取りで伝統的。二階建洋館は外壁を下見板張、一階に医院諸室を配し、Ｘ線室は大壁漆喰仕上。二階は床構え付一〇畳座敷に巡らした縁廊下に上下窓を開く。地域の医院として親しまれた佇まい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014582"},{"id":"00014583","register_sub_id":"101","register_pk":"515125","name":"旧広田医院門柱及び塀","kana":"きゅうひろたいいんもんちゅうおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県高座郡寒川町一之宮一丁目1126-1","lat":35.363575,"lng":139.384875,"geo_status":"db","era":"昭和4年／平成30年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門柱 コンクリート造、間口3.0m、袖塀付 塀 コンクリート造、総延長29m","structure_material":"門柱 コンクリート造","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0332","desc":"大山街道に開くコンクリート造門柱と塀基礎部分。門柱は太い角柱で、上部兜巾形で江戸切仕上の元は門扉付。袖柱を塀端部に立てて袖塀で塞ぎ、潜戸口を設ける。塀基礎は切石風モルタル仕上、元は板塀を載せた。医院表構えに相応しく重厚で歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014583"},{"id":"00013694","register_sub_id":"101","register_pk":"505211","name":"旧藤澤カントリー倶楽部クラブハウス（グリーンハウス）","kana":"きゅうふじさわかんとりーくらぶくらぶはうす（ぐりーんはうす）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市善行七丁目1-2","lat":35.36074167,"lng":139.47574167,"geo_status":"db","era":"昭和7年／令和2年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、瓦葺、建築面積786㎡、地下室付","structure_material":"鉄筋コンクリート造3階建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 291","desc":"Ａ・レーモンド設計。切妻造三階建の正面に車寄を張出し、背面に二階建をのばす。車寄など開口部の半円アーチによる構成、青緑色のスパニッシュ瓦葺屋根、アイアンワークの手摺など、全体をスパニッシュでまとめる。戦前のゴルフクラブハウスとしても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013694"},{"id":"00013371","register_sub_id":"101","register_pk":"368458","name":"材木座公会堂","kana":"ざいもくざこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市材木座四丁目356-1","lat":35.30763611,"lng":139.55270278,"geo_status":"db","era":"大正7年／平成9年頃改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋一部2階建、金属板葺、建築面積95㎡","structure_material":"木造平屋一部2階建","registered":"2020.08.17(令和2.08.17)","register_no":"14 － 0284","desc":"町民や別荘地の住民の寄付で建設した集会所兼防災施設、通り沿いの敷地に西面して建ち、敷地の南西隅に防火水槽を設置する。木造二階建、入母屋造金属板葺である。内部は広い一室の集会所で東面に床を構える。地域の集会所として現在も利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013371"},{"id":"00014775","register_sub_id":"101","register_pk":"519033","name":"山月庵","kana":"さんげつあん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24834722,"lng":139.04312222,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、檜皮葺一部こけら葺及び茅葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0343","desc":"強羅公園西の庭園神仙郷内に所在する茶室で、敷地中央北寄りに建つ。西面南に玄関を設け、中央の広間席八畳には畳床、琵琶床、香炉棚を飾る。東の茅葺屋根は三畳中板の小間で、蒲と煤竹の竿縁天井に吹寄丸太格天井を組合わせる。変化に富む近代数寄屋の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014775"},{"id":"00014776","register_sub_id":"101","register_pk":"519034","name":"日光殿（旧早雲寮）","kana":"にっこうでん（きゅうそううんりょう）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.2479,"lng":139.04363889,"geo_status":"db","era":"昭和24年／昭和26年増築、平成11年・令和3年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建一部地階付、こけら葺一部鉄板葺、建築面積640㎡","structure_material":"木造平屋建一部地階付","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0344","desc":"神仙郷の南東に建つ、吉田五十八設計の芸能鑑賞用の大広間棟。南面中央の玄関は地階に通じる。一階大広間は西寄りの小壁が廻る一郭と畳縁が当初の早雲寮に遡り、西に畳床を飾る。ここから南庭の芸能を観る。北東増築部は東寄りの床が一段高く舞台にもなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014776"},{"id":"00014779","register_sub_id":"101","register_pk":"519037","name":"箱根美術館休憩所","kana":"はこねびじゅつかんきゅうけいじょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24868333,"lng":139.04321111,"geo_status":"db","era":"昭和27年／昭和56年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"コンクリートブロック造平屋建、陸屋根、建築面積115㎡","structure_material":"コンクリートブロック造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0347","desc":"神仙郷の北辺東端に北側道路に面して建つ補強コンクリートブロック造の平屋建の建物。外壁は大壁風につくり、陸屋根は庇を延ばし、わずかに高さを違えて三段につくる。西面北に券売口、南側を休憩室と売店とする。南面に大きく窓を開け、庭園鑑賞用の休憩所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014779"},{"id":"00014778","register_sub_id":"101","register_pk":"519036","name":"箱根美術館別館","kana":"はこねびじゅつかんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24861667,"lng":139.04299722,"geo_status":"db","era":"昭和28年／昭和中期・同56年頃改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造2階建及びコンクリートブロック造平屋建、瓦葺、建築面積195㎡","structure_material":"鉄筋コンクリート造2階建及びコンクリートブロック造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0346","desc":"神仙郷の北辺中央に位置する美術館別館。補強コンクリートブロック造の平屋建の西に鉄筋コンクリート造二階建を増築。平屋は棟反りをつけた寄棟造、増築部は宝形造で青瓦葺とする。南面東寄りの玄関から展示室に入る。所蔵品に合わせて東洋趣味を加えた建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014778"},{"id":"00014777","register_sub_id":"101","register_pk":"519035","name":"箱根美術館本館","kana":"はこねびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24820556,"lng":139.04268889,"geo_status":"db","era":"昭和27年／昭和56年・平成７年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"鉄筋コンクリート造及びコンクリートブロック造3階建、瓦葺、建築面積431㎡","structure_material":"鉄筋コンクリート造及びコンクリートブロック造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0345","desc":"神仙郷の北西に位置し東面して建つ美術館。鉄筋コンクリート造で床スラブに中空コンクリートブロックを用いる。中央に玄関、階段室を設け、南北に二階建の展示室を延ばす。三階塔屋は棟反りある寄棟屋根青瓦葺とし、貴賓室を設けて景観と共に名品を鑑賞する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014777"},{"id":"00005981","register_sub_id":"101","register_pk":"106966","name":"喬柏園（旧柏崎公会堂）","kana":"きょうはくえん（きゅうかしわざきこうかいどう）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県柏崎市西本町3-2-8","lat":37.36738707,"lng":138.54640128,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積535㎡、塔屋・煙突及び地下室付","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2007.07.31(平成19.07.31)","register_no":"15 － 0256","desc":"南接する道路からやや奥まった位置に南面して建つ。間口１９ｍ，奥行８ｍ規模の棟の背面に，間口１６ｍ，奥行２２ｍ規模の棟が接続する鉄筋コンクリート造２階建。一部を３階建とする。外壁をタイル貼とし，円柱４本を並べる車寄を正面に張り出す公会堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005981"},{"id":"00007735","register_sub_id":"101","register_pk":"108717","name":"三条市歴史民俗産業資料館（旧武徳殿）","kana":"さんじょうしれきしみんぞくさんぎょうしりょうかん（きゅうぶとくでん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市本町3-990-1","lat":37.63196778,"lng":138.95673472,"geo_status":"db","era":"昭和10／昭和24増築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積674㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0311","desc":"三条市の市街地に、東面して建つ。木造平屋建で、旧武道場を中心に西北に旧弓道場、東南に旧貴賓室を付ける。旧武道場は千鳥破風付の入母屋造桟瓦葺で、周囲に下屋庇をまわし、正面に唐破風造の玄関、北面に裏玄関を付設する。装飾を抑え、厳粛な雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007735"},{"id":"00008270","register_sub_id":"101","register_pk":"133912","name":"第二藤巻医院石垣","kana":"だいにふじまきいいんいしがき","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県十日町市上野甲1350-1他","lat":37.1818454,"lng":138.74952303,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石積、総延長80m","structure_material":"石積","registered":"2010.09.10(平成22.09.10)","register_no":"15 － 0324","desc":"敷地西正面及び南北両側面に位置する。石積、総延長８０ｍ。信濃川の河原石を用い、仏の蓮華座のように積むことから蓮華積とも呼ばれる。正面最大の石は幅が１．２ｍほどもあり、南北両側面の奥にゆくほど積石が小さくなる。地域性の色濃い屋敷構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008270"},{"id":"00008269","register_sub_id":"101","register_pk":"133911","name":"第二藤巻医院本館","kana":"だいにふじまきいいんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県十日町市上野甲1350-1","lat":37.18182875,"lng":138.74973052,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積192㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"15 － 0323","desc":"道路に西面する敷地の中央に位置する。木造２階建、切妻造鉄板葺、建築面積１９２㎡。十字形平面で、病室や診察室、レントゲン室、居室部などゾーニングが明瞭である。外壁は板壁で、窓を規則的に配し、正面の車寄せや破風の持送りが左右対称の外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008269"},{"id":"00008438","register_sub_id":"101","register_pk":"134834","name":"高田世界館","kana":"たかだせかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市本町六丁目字下小町51-14","lat":37.11750858,"lng":138.24488387,"geo_status":"db","era":"明治44年／昭和後期改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦一部鉄板葺、建築面積331㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0332","desc":"本町通から三〇メートル奥に入った位置に東面して建つ。正面一五メートル奥行二三メートルの木造二階建。切妻造で、正面側を複雑な寄棟造とし、パラペットを付ける。内部にドリス風の柱をたてるなど、雁木や町家が建ち並ぶ界隈に残る洋風建築として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008438"},{"id":"00005808","register_sub_id":"101","register_pk":"106795","name":"森医院家財蔵","kana":"もりいいんかざいぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96730443,"lng":138.34721799,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0218","desc":"主屋南側に建ち，北側を正面とする。桁行６ｍ，梁間５ｍ，土蔵造２階建，切妻造，桟瓦葺，正面に奥行一間の下屋を設ける。外壁は下見板張とし，下屋前面にはガラス戸を付ける。正面入口扉と東側面上下階窓は漆喰仕上げとし，堅牢かつ上質な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005808"},{"id":"00005798","register_sub_id":"101","register_pk":"106786","name":"森医院主屋","kana":"もりいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.9674449,"lng":138.34721462,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積356㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0215","desc":"道路から入って正面に建つ。桁行２５ｍ，梁間１５ｍの主体部に増築部を付す。木造２階建，切妻造，桟瓦葺。平入りの既存建物の部材を使い明治４２年に建造し，主要軸部材を良く残すが，妻入りに変更した。茶の間上部を吹き抜けとする佐渡民家の特徴を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005798"},{"id":"00005810","register_sub_id":"101","register_pk":"106797","name":"森医院外便所","kana":"もりいいんそとべんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96729797,"lng":138.34715054,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0220","desc":"敷地西辺に接して家財蔵と主屋増築部の間に建つ。桁行２．１ｍ，梁間１．５ｍの木造平屋建，切妻造，鉄板葺で，外部は波形鉄板及び横板張とする。正面軒を出桁造とし，内部は２室に区切る。裏庭の景観を構成する要素のひとつとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005810"},{"id":"00005813","register_sub_id":"101","register_pk":"106800","name":"森医院中門","kana":"もりいいんちゅうもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96724888,"lng":138.34725835,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0222","desc":"主屋東側庭園の際に建ち，間口２．１ｍ，木造，腕木門，切妻造，桟瓦葺とする。主屋東側に広がる庭園と敷地南側の生活空間を隔てる境界をなす。間口の比較的大きな門であるが，造作は単純で簡素である。庭園の景観と一体となり，落着きのある空間を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005813"},{"id":"00005809","register_sub_id":"101","register_pk":"106796","name":"森医院納屋","kana":"もりいいんなや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96726139,"lng":138.34734481,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積53㎡、門付","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0219","desc":"主屋の南側に建つ。桁行１２ｍ，梁間４．５ｍ，木造２階建，切妻造，桟瓦葺で，北面に庇を付け，西面南端に脇門を設ける。納屋として規模が大きく，また主屋や病院棟の建築以前に建てられ，味噌蔵と共にかつての屋敷構えの景観を留めるひとつとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005809"},{"id":"00005802","register_sub_id":"101","register_pk":"106790","name":"森医院病院棟","kana":"もりいいんびょういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.967583,"lng":138.34708473,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0216","desc":"主屋の北寄りに接続し，前庭に面する。桁行１４ｍ，梁間９ｍ，木造２階建，寄棟造，桟瓦葺。外壁は柱内を下見板張とし，軒を持送りで支持する。北及び東側屋根面に手摺付の切妻屋根を造り，アクセントとする。緑色を基調とした，特徴的な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005802"},{"id":"00005805","register_sub_id":"101","register_pk":"106792","name":"森医院味噌蔵","kana":"もりいいんみそぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96726676,"lng":138.3470147,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0217","desc":"主屋西側の増築部の南側に接続し，北側を正面とする。桁行３．６ｍ，梁間３ｍ，土蔵造２階建，切妻造，桟瓦葺。外壁はモルタル塗及び鉄板張とする。主屋や病院棟の建築以前に建てられており，納屋と共にかつての屋敷構えの景観を留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005805"},{"id":"00005812","register_sub_id":"101","register_pk":"106799","name":"森医院門","kana":"もりいいんもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市真野新町502-甲","lat":37.96749315,"lng":138.34690369,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、間口3.8m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0221","desc":"敷地北東面の前面道路に面して立つ表門。柱間３．８ｍ，高さ２．８ｍ，石造。３０㎝角の石柱を基壇上に建て，表面を小叩き仕上げとし，隅部は磨き仕上げ，頂部は半球形に成形する。扉はもともと設けない。広大な敷地の入口を画し，格式ある表構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005812"},{"id":"00011112","register_sub_id":"101","register_pk":"205219","name":"良寛記念館回廊","kana":"りょうかんきねんかんかいろう","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三島郡出雲崎町大字米田字十二社ノ上12-2他","lat":37.542377,"lng":138.688263,"geo_status":"db","era":"昭和39","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、延長23m","structure_material":"鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0454","desc":"管理棟と展示棟を結ぶ回廊。南側に壁を建て、片持状に床と屋根を張り出す。両棟と相まって庭を画するのみならず、展示棟を聖なる世界に見立て、その媒介としての強い意義を与えられていたと伝えられ、記念館全体の空間構成を有機的にまとめる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011112"}];
